describe('"destroy that creature at end of combat": the basilisks (D969)', () => {
  const C = (name: string, text: string, extra: Record<string, unknown> = {}) => ({ name, type_line: 'Creature — Basilisk', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '0', toughness: '6', ...extra });
  const ROWS = [
    C('Test Basilisk', 'Whenever this creature blocks or becomes blocked by a creature, destroy that creature at end of combat.'),
    C('Test Gaze', 'Whenever this creature blocks or becomes blocked by a non-Wall creature, destroy that creature at end of combat.'),
    C('Test Stare', 'Whenever this creature blocks or becomes blocked by a nonblack creature, destroy that creature at end of combat.'),
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Shade', type_line: 'Creature — Shade', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Wall', type_line: 'Creature — Wall', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', power: '0', toughness: '4' },
  ];
  const deck = customDeck({
    id: 'd969', name: 'Basilisks',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 48 }],
    data: ROWS as never[],
  });
  /** Seat 1 attacks with `attacker`; seat 0 blocks with `blocker`. Returns the state at combat damage and after combat. */
  const fight = (blocker: string, attacker: string) => {
    let s = advanceTo(arena({
      decks: { 0: 'd969', 1: 'd969' }, deckSpecs: { d969: deck.deck },
      battlefield: { 0: [blocker], 1: [attacker] }, turn: 3, firstSeat: 1,
    }), 'declare-attackers');
    const them = find(s, 1, 'battlefield', attacker);
    s = apply(s, { type: 'auto:attack', by: 1, attackers: [{ attacker: them, defender: 0 }] });
    s = advanceTo(s, 'declare-blockers');
    s = apply(s, { type: 'auto:block', by: 0, blocks: [{ blocker: find(s, 0, 'battlefield', blocker), attacker: them }] });
    for (let i = 0; i < 6 && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    const during = drain(advanceTo(s, 'combat-damage'), 30);
    const after = drain(advanceTo(s, 'postcombat-main'), 30);
    return { them, during, after };
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 3)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
  });

  it('the creature it blocks is destroyed at end of combat, not before', () => {
    const { them, during, after } = fight('Test Basilisk', 'Test Bear');
    expect(during.instances[them]!.zone).toBe('battlefield');
    expect(after.instances[them]!.zone).toBe('graveyard');
  });

  it('a non-Wall basilisk spares a Wall; a nonblack one spares a black creature and not a green one', () => {
    const wall = fight('Test Gaze', 'Test Wall');
    expect(wall.after.instances[wall.them]!.zone).toBe('battlefield');
    const shade = fight('Test Stare', 'Test Shade');
    expect(shade.after.instances[shade.them]!.zone).toBe('battlefield');
    const bear = fight('Test Stare', 'Test Bear');
    expect(bear.after.instances[bear.them]!.zone).toBe('graveyard');
  });
});

describe('a chosen discard or exile with a mana value or a type list (D970)', () => {
  const S = (name: string, text: string) => ({ name, type_line: 'Sorcery', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal' });
  const ROWS = [
    S('Test Duress', 'Target player reveals their hand. You choose a nonland card from it with mana value 3 or less. That player discards that card.'),
    S('Test Pluck', 'Target opponent reveals their hand. You choose an artifact, instant, or sorcery card from it and exile that card.'),
    S('Test Squeeze', 'Target opponent reveals their hand. You choose a noncreature, nonland card from it. That player discards that card.'),
    S('Test Bare', 'Target opponent reveals their hand. You choose a nonlegendary, nonland card from it. That player discards that card.'),
    { name: 'Test Crown', type_line: 'Legendary Artifact', oracle_text: '', mana_cost: '{1}', cmc: 1, colors: [], layout: 'normal' },
    { name: 'Test Cheap', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{1}{G}', cmc: 2, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Dear', type_line: 'Creature — Giant', oracle_text: '', mana_cost: '{4}{G}', cmc: 5, colors: ['G'], layout: 'normal', power: '5', toughness: '5' },
    { name: 'Test Trinket', type_line: 'Artifact', oracle_text: '', mana_cost: '{1}', cmc: 1, colors: [], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd970', name: 'Chosen discards',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Swamp', count: 45 }],
    data: ROWS as never[],
  });
  /** Casts `card` at seat 1, whose hand is `theirs`; returns the question asked and the state. */
  const castAt = (card: string, theirs: string[]) => {
    const s = advanceTo(arena({
      decks: { 0: 'd970', 1: 'd970' }, deckSpecs: { d970: deck.deck }, hands: { 0: [card], 1: theirs },
      battlefield: { 0: ['Swamp'], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    let t = drain(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card), targets: [{ kind: 'player', seat: 1 }] } as Action), 30);
    for (let i = 0; i < 6 && t.pendingDecision === null && t.stackOrder.length > 0; i++) t = passBoth(t);
    return t;
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 4)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
  });

  it('"a noncreature, nonland card": the artifact is taken, the creature and the land stay', () => {
    const t = castAt('Test Squeeze', ['Test Cheap', 'Test Trinket', 'Swamp']);
    expect(t.pendingDecision).toBeNull();
    expect(namesIn(t, 1, 'graveyard')).toContain('Test Trinket');
    expect(namesIn(t, 1, 'hand')).toEqual(expect.arrayContaining(['Test Cheap', 'Swamp']));
  });

  it('"a nonlegendary, nonland card": the legendary artifact stays, the creature is taken', () => {
    const t = castAt('Test Bare', ['Test Crown', 'Test Cheap', 'Swamp']);
    expect(t.pendingDecision).toBeNull();
    expect(namesIn(t, 1, 'graveyard')).toContain('Test Cheap');
    expect(namesIn(t, 1, 'hand')).toEqual(expect.arrayContaining(['Test Crown', 'Swamp']));
  });

  it('"with mana value 3 or less": the only card that fits is taken, and the dear one stays', () => {
    // With one card that fits, the question answers itself; a filter that let the 5-drop in would
    // leave it open, and both cards in hand.
    const t = castAt('Test Duress', ['Test Cheap', 'Test Dear', 'Swamp']);
    expect(t.pendingDecision).toBeNull();
    expect(namesIn(t, 1, 'graveyard')).toContain('Test Cheap');
    expect(namesIn(t, 1, 'hand')).toEqual(expect.arrayContaining(['Test Dear', 'Swamp']));
  });

  it('"an artifact, instant, or sorcery card": the artifact is exiled, the creatures stay', () => {
    const t = castAt('Test Pluck', ['Test Cheap', 'Test Trinket', 'Test Dear']);
    expect(t.pendingDecision).toBeNull();
    expect(namesIn(t, 1, 'exile')).toContain('Test Trinket');
    expect(namesIn(t, 1, 'hand')).toEqual(expect.arrayContaining(['Test Cheap', 'Test Dear']));
  });
});

describe('connive (D971)', () => {
  const ROWS = [
    { name: 'Test Schemer', type_line: 'Creature — Rogue', oracle_text: 'When this creature enters, it connives.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal', power: '1', toughness: '1' },
    { name: 'Test Plotter', type_line: 'Creature — Rogue', oracle_text: '{0}: This creature connives.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal', power: '1', toughness: '1' },
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
  ];
  const deck = customDeck({
    id: 'd971', name: 'Connive',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Island', count: 51 }],
    data: ROWS as never[],
  });
  /** Casts the Schemer with `hand` beside it; returns the state at the discard question. */
  const conniving = (hand: string[]) => {
    const s = advanceTo(arena({
      decks: { 0: 'd971', 1: 'd971' }, deckSpecs: { d971: deck.deck }, hands: { 0: ['Test Schemer', ...hand] },
      battlefield: { 0: ['Island'], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const top = ids(s, 0, 'library')[0]!;
    let t = drain(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Schemer') } as Action), 30);
    for (let i = 0; i < 8 && t.pendingDecision === null && t.stackOrder.length > 0; i++) t = passBoth(t);
    return { t, top, schemer: find(t, 0, 'battlefield', 'Test Schemer') };
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 2)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
  });

  it('draws first: the card drawn is one of the cards it may discard', () => {
    const { t, top } = conniving(['Test Bear']);
    expect(t.pendingDecision?.candidates).toEqual(expect.arrayContaining([top]));
  });

  it('a nonland card discarded: a +1/+1 counter; a land discarded: none', () => {
    const one = conniving(['Test Bear', 'Island']);
    const bear = find(one.t, 0, 'hand', 'Test Bear');
    const withBear = drain(apply(one.t, { type: 'auto:decide', by: 0, cards: [bear] } as Action), 30);
    expect(withBear.instances[bear]!.zone).toBe('graveyard');
    expect(withBear.instances[one.schemer]!.counters['+1/+1']).toBe(1);
    const two = conniving(['Test Bear', 'Island']);
    const land = find(two.t, 0, 'hand', 'Island');
    const withLand = drain(apply(two.t, { type: 'auto:decide', by: 0, cards: [land] } as Action), 30);
    expect(withLand.instances[land]!.zone).toBe('graveyard');
    expect(withLand.instances[two.schemer]!.counters['+1/+1'] ?? 0).toBe(0);
  });
});

describe('an Equipment that attaches as it enters, then acts on that creature (D972)', () => {
  const ROWS = [
    { name: 'Test Lance', type_line: 'Artifact — Equipment', oracle_text: 'When this Equipment enters, attach it to target creature you control. That creature gains first strike until end of turn.\nEquipped creature gets +1/+0.\nEquip {2}', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal' },
    { name: 'Test Spur', type_line: 'Artifact — Equipment', oracle_text: 'When this Equipment enters, attach it to target creature you control. Untap that creature.\nEquipped creature gets +1/+1.\nEquip {1}', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal' },
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
  ];
  const deck = customDeck({
    id: 'd972', name: 'Arrives attached',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Plains', count: 51 }],
    data: ROWS as never[],
  });
  /** Casts `card` with two bears out (one tapped), aiming the trigger at the tapped one. */
  const enter = (card: string) => {
    let s = advanceTo(arena({
      decks: { 0: 'd972', 1: 'd972' }, deckSpecs: { d972: deck.deck }, hands: { 0: [card] },
      battlefield: { 0: ['Plains', 'Test Bear', 'Test Bear'], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const [bear, other] = ids(s, 0, 'battlefield').filter((id) => nameOf(s, id) === 'Test Bear');
    s = { ...s, instances: { ...s.instances, [bear!]: { ...s.instances[bear!]!, tapped: true } } };
    const equipment = find(s, 0, 'hand', card);
    s = drain(apply(s, { type: 'auto:cast', by: 0, card: equipment } as Action), 30);
    for (let i = 0; i < 10 && (s.stackOrder.length > 0 || s.pendingChoice !== null); i++) {
      s = s.pendingChoice !== null
        ? drain(apply(s, { type: 'auto:choose', by: 0, targets: [{ kind: 'card', id: bear! }] }), 30)
        : drain(passBoth(s), 30);
    }
    return { s, bear: bear!, other: other!, equipment };
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 2)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
    // A follow-up with a target of its own would be handed the host creature, so it stays unread.
    const own = compileCard({ ...ROWS[0], name: 'Test Wrecker', oracle_text: 'When this Equipment enters, attach it to target creature you control. Destroy target artifact.\nEquipped creature gets +1/+0.\nEquip {2}' } as never);
    expect(own.ok && own.unread.length).toBeGreaterThan(0);
  });

  it('attached, with its bonus, and first strike on that creature only', () => {
    const { s, bear, other, equipment } = enter('Test Lance');
    expect(s.instances[equipment]!.attachedTo).toBe(bear);
    const got = characteristicsOf(s, s.instances[bear]!);
    expect(got.power).toBe(3);
    expect([...got.keywords]).toContain('first strike');
    expect([...characteristicsOf(s, s.instances[other]!).keywords]).not.toContain('first strike');
  });

  it('"Untap that creature": the tapped creature it attached to is untapped', () => {
    const { s, bear, equipment } = enter('Test Spur');
    expect(s.instances[equipment]!.attachedTo).toBe(bear);
    expect(s.instances[bear]!.tapped).toBe(false);
  });
});

describe('spells cast from the top of the library, and Bolas\'s Citadel\'s life (D731)', () => {
  const row = (name: string, type: string, text: string, cost = '{3}{B}{B}{B}', cmc = 6, colors = ['B']) => ({
    name, type_line: type, oracle_text: text, mana_cost: cost, cmc, colors, layout: 'normal',
  });
  const ROWS = [
    row('Test Citadel', 'Legendary Artifact', 'You may look at the top card of your library any time.\nYou may play lands and cast spells from the top of your library. If you cast a spell this way, pay life equal to its mana value rather than pay its mana cost.'),
    { ...row('Test Vizier', 'Creature — Naga Cleric', 'You may cast creature spells from the top of your library.', '{3}{G}', 4, ['G']), power: '3', toughness: '4' },
    { ...row('Test Bear', 'Creature — Bear', '', '{1}{G}', 2, ['G']), power: '2', toughness: '2' },
    // Green, so the Forests could pay its mana cost: a mana cast refused is refused for the permission.
    row('Test Divination', 'Sorcery', 'Draw two cards.', '{2}{G}', 3, ['G']),
    { ...row('Test Sigarda', 'Creature — Angel', 'You may cast Elf spells and Bear spells from the top of your library.', '{5}', 5, []), power: '4', toughness: '4' },
  ];
  const deck = customDeck({
    id: 'd731', name: 'Citadel',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 44 }],
    data: ROWS as never[],
  });
  const table = (battlefield: readonly string[], firstSeat: 0 | 1 = 0) => advanceTo(arena({
    decks: { 0: 'd731', 1: 'd731' }, deckSpecs: { d731: deck.deck }, battlefield: { 0: [...battlefield] }, turn: 3, firstSeat,
  }), 'precombat-main');
  const onTop = (s: GameState, name: string): GameState =>
    apply(s, { type: 'card:move', by: 0, card: find(s, 0, 'library', name), toZone: 'library', position: 'top' });
  const top = (s: GameState) => ids(s, 0, 'library')[0]!;
  const rowsFor = (s: GameState) => legalActions(s, 0).plays.filter((p) => p.card === top(s));

  it('reads the family, and leaves a kind with a condition on it unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const reads = (text: string) => compileCard(row('Test Line', 'Enchantment', text) as never);
    for (const text of [
      'You may play lands and cast spells from the top of your library.',
      'You may cast artifact spells and colorless spells from the top of your library.',
      'You may cast Angel spells and Human spells from the top of your library.',
      'You may cast Cleric, Rogue, Warrior, and Wizard spells from the top of your library.',
      'You may cast instant and sorcery spells from the top of your library.',
    ]) expect(reads(text), text).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      'You may cast spells with flash or flying from the top of your library.',
      'You may cast creature spells with power 4 or greater from the top of your library. If you cast a creature spell this way, it gains haste until end of turn.',
      'You may cast noncreature spells from the top of your library. If you cast a spell this way, you may cast it as though it had flash.',
      'You may cast historic spells from the top of your library.',
    ]) { const read = reads(text); expect(read.ok && read.unread.length, text).toBe(1); }
  });

  it('casts the top card for life equal to its mana value, and offers no mana cast beside it', () => {
    let s = onTop(table(['Test Citadel', 'Forest', 'Forest', 'Forest']), 'Test Divination');
    const card = top(s);
    const rows = rowsFor(s);
    expect(rows.map((p) => p.description)).toEqual(['Cast Test Divination for its cost from the top of your library (3 life)']);
    expect(refusal(s, { type: 'auto:cast', by: 0, card })).toMatch(/for life, not for its mana cost/);
    const life = s.seats[0]!.life;
    s = apply(s, { type: 'auto:cast', by: 0, card, payLifeFromTop: true });
    expect(s.seats[0]!.life).toBe(life - 3);
    expect(s.instances[card]!.zone).toBe('stack');
    // Nothing tapped: the mana cost was not paid.
    expect(ids(s, 0, 'battlefield').every((id) => s.instances[id]!.tapped !== true)).toBe(true);
    const hand = ids(s, 0, 'hand').length;
    s = drain(passBoth(s));
    expect(ids(s, 0, 'hand').length).toBe(hand + 2);
    expect(s.instances[card]!.zone).toBe('graveyard');
  });

  it('offers a land on top as the land drop, and a spell only while the life is there', () => {
    const land = onTop(table(['Test Citadel']), 'Forest');
    expect(rowsFor(land).map((p) => p.description)).toEqual(['Play Forest from the top of your library']);
    const s = onTop(table(['Test Citadel']), 'Test Citadel');
    const poor = { ...s, seats: s.seats.map((seat) => (seat.index === 0 ? { ...seat, life: 6 } : seat)) } as GameState;
    expect(rowsFor(poor)).toEqual([]);
    expect(rowsFor(s).length).toBe(1);
    // And refused without the Citadel.
    const bare = onTop(table([]), 'Test Divination');
    expect(rowsFor(bare)).toEqual([]);
    expect(refusal(bare, { type: 'auto:cast', by: 0, card: top(bare), payLifeFromTop: true })).toMatch(/nothing lets you/);
    expect(refusal(bare, { type: 'auto:cast', by: 0, card: top(bare) })).toMatch(/nothing lets you/);
    // Only the top card: the one under it is still in the library.
    const under = onTop(onTop(table(['Test Citadel']), 'Test Divination'), 'Forest');
    const second = ids(under, 0, 'library')[1]!;
    expect(nameOf(under, second)).toBe('Test Divination');
    expect(refusal(under, { type: 'auto:cast', by: 0, card: second, payLifeFromTop: true })).toMatch(/nothing lets you|not in your hand/);
  });

  it('shows its controller the top card and nobody else', () => {
    const s = onTop(table(['Test Citadel']), 'Test Divination');
    expect(viewFor(s, 0).seats[0]!.libraryTop).toBe(top(s));
    expect(viewFor(s, 0).cards[top(s)]?.card?.name).toBe('Test Divination');
    expect(viewFor(s, 1).seats[0]!.libraryTop).toBeUndefined();
    expect(viewFor(s, 1).cards[top(s)]).toBeUndefined();
    const bare = onTop(table([]), 'Test Divination');
    expect(viewFor(bare, 0).cards[top(bare)]).toBeUndefined();
  });

  it('a kind permission casts its kind at the printed cost and at its timing, and nothing else', () => {
    let s = onTop(table(['Test Vizier', 'Forest', 'Forest']), 'Test Bear');
    const bear = top(s);
    expect(rowsFor(s).map((p) => p.description)).toEqual(['Cast Test Bear']);
    expect(refusal(s, { type: 'auto:cast', by: 0, card: bear, payLifeFromTop: true })).toMatch(/for life/);
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: bear })));
    expect(s.instances[bear]!.zone).toBe('battlefield');
    // A sorcery on top is not its kind, and neither is a land: no land permission.
    const sorcery = onTop(table(['Test Vizier', 'Forest', 'Forest', 'Forest']), 'Test Divination');
    expect(rowsFor(sorcery)).toEqual([]);
    expect(refusal(sorcery, { type: 'auto:cast', by: 0, card: top(sorcery) })).toMatch(/nothing lets you/);
    const land = onTop(table(['Test Vizier']), 'Forest');
    expect(rowsFor(land)).toEqual([]);
    // On the opponent's turn, a creature is not cast at all.
    const theirs = apply(onTop(table(['Test Vizier', 'Forest', 'Forest'], 1), 'Test Bear'), { type: 'auto:pass', by: 1 });
    expect(theirs.priority).toBe(0);
    expect(legalActions(theirs, 0).plays.some((p) => p.card === top(theirs))).toBe(false);
    expect(refusal(theirs, { type: 'auto:cast', by: 0, card: top(theirs) })).toMatch(/main phase/);
  });

  it('a permission naming two kinds casts either one', () => {
    const s = onTop(table(['Test Sigarda', 'Forest', 'Forest']), 'Test Bear');
    expect(rowsFor(s).map((p) => p.description)).toEqual(['Cast Test Bear']);
  });
});

describe('revealing the top cards and putting one into your hand (D1075)', () => {
  const S = (name: string, text: string) => ({ name, type_line: 'Sorcery', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal' });
  const ROWS = [
    S('Test Salvage', 'Reveal the top five cards of your library. You may put a creature or land card from among them into your hand. Put the rest into your graveyard.'),
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Relic', type_line: 'Artifact', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd1075', name: 'Salvage',
    entries: [{ name: 'Test Salvage', count: 1 }, { name: 'Test Bear', count: 20 }, { name: 'Test Relic', count: 20 }, { name: 'Forest', count: 19 }],
    data: ROWS as never[],
  });
  const dig = () => {
    const s = advanceTo(arena({
      decks: { 0: 'd1075', 1: 'd1075' }, deckSpecs: { d1075: deck.deck }, hands: { 0: ['Test Salvage'] },
      battlefield: { 0: [], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    let t = drain(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Salvage') } as Action), 30);
    for (let i = 0; i < 6 && t.pendingDecision === null && t.stackOrder.length > 0; i++) t = passBoth(t);
    const looked = ids(t, 0, 'library').slice(0, 5);
    return { t, looked, answer: (cards: string[]) => drain(apply(t, { type: 'auto:decide', by: 0, cards } as Action), 30) };
  };

  it('reads whole; "and/or" of two kinds stays unread', () => {
    expect(deck.unknown).toEqual([]);
    expect(compileCard(ROWS[0] as never)).toMatchObject({ ok: true, unread: [] });
    const odd = compileCard(S('Test Odd', 'Reveal the top four cards of your library. You may put a creature card and/or a land card from among them into your hand. Put the rest into your graveyard.') as never);
    expect(odd.ok && odd.unread.length).toBe(1);
  });

  it('a creature or land offered, at most one taken, the rest to the graveyard', () => {
    const { t, looked, answer } = dig();
    const offered = t.pendingDecision?.candidates ?? [];
    expect(offered.every((id) => nameOf(t, id) !== 'Test Relic')).toBe(true);
    expect(t.pendingDecision?.max).toBe(1);
    const pick = offered[0]!;
    const done = answer([pick]);
    expect(done.instances[pick]!.zone).toBe('hand');
    for (const id of looked.filter((id) => id !== pick)) expect(done.instances[id]!.zone).toBe('graveyard');
  });
});

describe('digging onto the battlefield, and revealing up to two (D973)', () => {
  const S = (name: string, text: string) => ({ name, type_line: 'Sorcery', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal' });
  const ROWS = [
    S('Test Ramp', 'Look at the top seven cards of your library. Put up to two land cards from among them onto the battlefield tapped. Put the rest on the bottom of your library in a random order.'),
    S('Test Call', 'Look at the top seven cards of your library. You may put a creature card from among them onto the battlefield. Put the rest on the bottom of your library in a random order.'),
    S('Test Salvage', 'Look at the top seven cards of your library. You may reveal up to two artifact cards from among them and put them into your hand. Put the rest on the bottom of your library in a random order.'),
    S('Test Muster', 'Look at the top seven cards of your library. Put up to two creature cards with mana value 3 or less from among them onto the battlefield. Put the rest on the bottom of your library in a random order.'),
    { name: 'Test Giant', type_line: 'Creature — Giant', oracle_text: '', mana_cost: '{4}{G}', cmc: 5, colors: ['G'], layout: 'normal', power: '5', toughness: '5' },
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Relic', type_line: 'Artifact', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd973', name: 'Digs',
    entries: [{ name: 'Test Ramp', count: 1 }, { name: 'Test Call', count: 1 }, { name: 'Test Salvage', count: 1 }, { name: 'Test Muster', count: 1 }, { name: 'Test Bear', count: 14 }, { name: 'Test Giant', count: 14 }, { name: 'Test Relic', count: 14 }, { name: 'Forest', count: 14 }],
    data: ROWS as never[],
  });
  /** Casts `card`; returns the question, the seven looked at, and a function answering it. */
  const dig = (card: string) => {
    const s = advanceTo(arena({
      decks: { 0: 'd973', 1: 'd973' }, deckSpecs: { d973: deck.deck }, hands: { 0: [card] },
      battlefield: { 0: [], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    let t = drain(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card) } as Action), 30);
    for (let i = 0; i < 6 && t.pendingDecision === null && t.stackOrder.length > 0; i++) t = passBoth(t);
    const looked = ids(t, 0, 'library').slice(0, 7);
    return { t, looked, answer: (cards: string[]) => drain(apply(t, { type: 'auto:decide', by: 0, cards } as Action), 30) };
  };
  const kind = (s: GameState, id: string) => nameOf(s, id);

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 4)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
    // "Up to two" is the most that may be taken, whatever the seven turn out to hold.
    const salvage = compileCard(ROWS[2] as never);
    expect(salvage.ok && (salvage.script?.decisions?.[0] as { max?: number } | undefined)?.max).toBe(2);
    // "And/or" is the "or" list.
    expect(compileCard(S('Test Study', 'Look at the top four cards of your library. You may reveal up to two instant and/or sorcery cards from among them and put the revealed cards into your hand. Put the rest on the bottom of your library in a random order.') as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('"with mana value 3 or less": the bears are offered, the 5-mana giants are not', () => {
    const { t } = dig('Test Muster');
    const offered = t.pendingDecision?.candidates ?? [];
    expect(offered.length).toBeGreaterThan(0);
    expect(offered.every((id) => kind(t, id) === 'Test Bear')).toBe(true);
  });

  it('up to two lands onto the battlefield tapped; only lands offered; the rest to the bottom', () => {
    const { t, looked, answer } = dig('Test Ramp');
    const offered = t.pendingDecision?.candidates ?? [];
    expect(offered.length).toBeGreaterThan(0);
    expect(offered.every((id) => kind(t, id) === 'Forest')).toBe(true);
    const picked = offered.slice(0, 2);
    const done = answer(picked);
    for (const id of picked) {
      expect(done.instances[id]!.zone).toBe('battlefield');
      expect(done.instances[id]!.tapped).toBe(true);
    }
    const rest = looked.filter((id) => !picked.includes(id));
    expect(ids(done, 0, 'library').slice(-rest.length).sort()).toEqual([...rest].sort());
  });

  it('a creature onto the battlefield, untapped; or none', () => {
    const { t, answer } = dig('Test Call');
    const offered = t.pendingDecision?.candidates ?? [];
    expect(offered.every((id) => kind(t, id) === 'Test Bear' || kind(t, id) === 'Test Giant')).toBe(true);
    const done = answer([offered[0]!]);
    expect(done.instances[offered[0]!]!.zone).toBe('battlefield');
    expect(done.instances[offered[0]!]!.tapped).toBe(false);
    const none = answer([]);
    expect(ids(none, 0, 'battlefield')).toHaveLength(0);
  });

  it('up to two artifacts into the hand, not three', () => {
    const { t, answer } = dig('Test Salvage');
    expect(t.pendingDecision?.max).toBe(2);
    const offered = t.pendingDecision?.candidates ?? [];
    expect(offered.every((id) => kind(t, id) === 'Test Relic')).toBe(true);
    const picked = offered.slice(0, 2);
    const done = answer(picked);
    for (const id of picked) expect(done.instances[id]!.zone).toBe('hand');
  });
});

describe('a counted sacrifice: "Sacrifice two creatures", and Bolas\'s Citadel\'s ten (D732)', () => {
  const row = (name: string, type: string, text: string, extra: Record<string, string> = {}) => ({
    name, type_line: type, oracle_text: text, mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', ...extra,
  });
  const ROWS = [
    row('Test Citadel', 'Legendary Artifact', 'You may look at the top card of your library any time.\nYou may play lands and cast spells from the top of your library. If you cast a spell this way, pay life equal to its mana value rather than pay its mana cost.\n{T}, Sacrifice ten nonland permanents: Each opponent loses 10 life.'),
    row('Test Altar', 'Artifact', '{T}, Sacrifice two creatures: Draw a card.'),
    row('Test Chieftain', 'Creature — Elf', 'Sacrifice two other creatures: Draw a card.', { power: '1', toughness: '1' }),
    row('Test Elf', 'Creature — Elf', '', { power: '1', toughness: '1' }),
    row('Test Bear', 'Creature — Bear', '', { power: '2', toughness: '2' }),
    row('Test Outlet', 'Artifact', 'Sacrifice a creature: Draw a card.'),
  ];
  const deck = customDeck({
    id: 'd732', name: 'Counted',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 10 })), { name: 'Forest', count: 20 }],
    data: ROWS as never[],
  });
  const table = (battlefield: readonly string[]) => advanceTo(arena({
    decks: { 0: 'd732', 1: 'd732' }, deckSpecs: { d732: deck.deck }, battlefield: { 0: [...battlefield] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const playOf = (s: GameState, name: string) =>
    legalActions(s, 0).plays.find((p) => p.kind === 'activate' && p.card === find(s, 0, 'battlefield', name));

  it('reads the family, and leaves a count it has no number for unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 3)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const reads = (text: string) => compileCard(row('Test Line', 'Artifact', text) as never);
    for (const text of [
      '{2}, {T}, Sacrifice three Foods: Draw a card.',
      'Sacrifice three Blood tokens: Draw a card.',
      'Sacrifice two Mountains: Draw a card.',
      'Sacrifice two Elves: Draw a card.',
      'Sacrifice two other artifacts and/or creatures: Draw a card.',
    ]) expect(reads(text), text).toMatchObject({ ok: true, unread: [] });
    for (const text of ['Sacrifice X creatures: Draw a card.', 'Sacrifice two other lands: Draw a card.']) {
      const read = reads(text);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it('the Citadel sacrifices ten nonland permanents, itself among them if chosen, and each opponent loses 10', () => {
    let s = table(['Test Citadel', ...Array(9).fill('Test Bear'), 'Forest', 'Forest']);
    const play = playOf(s, 'Test Citadel')!;
    expect(play.sacrificeCount).toBe(10);
    // Every nonland permanent and no land.
    expect(play.sacrificeOptions.map((id) => nameOf(s, id)).sort()).toEqual(['Test Bear', 'Test Bear', 'Test Bear',
      'Test Bear', 'Test Bear', 'Test Bear', 'Test Bear', 'Test Bear', 'Test Bear', 'Test Citadel']);
    const victims = [...play.sacrificeOptions];
    const citadel = find(s, 0, 'battlefield', 'Test Citadel');
    const life = s.seats[1]!.life;
    s = apply(s, { type: 'auto:activate', by: 0, card: citadel, abilityIndex: play.abilityIndex ?? 0, sacrifices: victims });
    for (const id of victims) expect(s.instances[id]!.zone, nameOf(s, id)).toBe('graveyard');
    expect(namesIn(s, 0, 'battlefield')).toEqual(['Forest', 'Forest']);
    s = drain(passBoth(s));
    expect(s.seats[1]!.life).toBe(life - 10);
  });

  it('is not offered with nine, and refuses the wrong count, a repeat, a land and a single sacrifice', () => {
    const nine = table(['Test Citadel', ...Array(8).fill('Test Bear'), 'Forest']);
    expect(playOf(nine, 'Test Citadel')).toBeUndefined();
    const s = table(['Test Citadel', ...Array(10).fill('Test Bear'), 'Forest']);
    const citadel = find(s, 0, 'battlefield', 'Test Citadel');
    const bears = ids(s, 0, 'battlefield').filter((id) => nameOf(s, id) === 'Test Bear');
    const forest = find(s, 0, 'battlefield', 'Forest');
    const at = { type: 'auto:activate' as const, by: 0 as const, card: citadel, abilityIndex: playOf(s, 'Test Citadel')!.abilityIndex ?? 0 };
    expect(refusal(s, { ...at, sacrifices: bears.slice(0, 9) })).toMatch(/choose 10 different/);
    expect(refusal(s, { ...at, sacrifices: [...bears.slice(0, 9), bears[0]!] })).toMatch(/choose 10 different/);
    expect(refusal(s, { ...at, sacrifices: [...bears.slice(0, 9), forest] })).toMatch(/cannot be sacrificed/);
    expect(refusal(s, { ...at, sacrifice: bears[0]! })).toMatch(/choose 10 different/);
    // And a single-sacrifice ability refuses a list.
    const altar = table(['Test Chieftain', 'Test Elf', 'Test Bear']);
    const one = playOf(altar, 'Test Chieftain')!;
    expect(one.sacrificeCount).toBe(2);
  });

  it('"two other creatures" never takes the source, and "two creatures" may', () => {
    const s = table(['Test Chieftain', 'Test Elf', 'Test Bear']);
    const chieftain = find(s, 0, 'battlefield', 'Test Chieftain');
    expect(playOf(s, 'Test Chieftain')!.sacrificeOptions).not.toContain(chieftain);
    expect(playOf(table(['Test Chieftain', 'Test Elf']), 'Test Chieftain')).toBeUndefined();
    const altar = table(['Test Altar', 'Test Elf', 'Test Bear']);
    const play = playOf(altar, 'Test Altar')!;
    expect(play.sacrificeOptions.map((id) => nameOf(altar, id)).sort()).toEqual(['Test Bear', 'Test Elf']);
    const hand = ids(altar, 0, 'hand').length;
    const next = drain(passBoth(apply(altar, {
      type: 'auto:activate', by: 0, card: find(altar, 0, 'battlefield', 'Test Altar'), abilityIndex: play.abilityIndex ?? 0,
      sacrifices: [...play.sacrificeOptions],
    })));
    expect(namesIn(next, 0, 'graveyard').sort()).toEqual(['Test Bear', 'Test Elf']);
    expect(ids(next, 0, 'hand').length).toBe(hand + 1);
    // And a list on an ability that sacrifices one thing is refused.
    const outlet = table(['Test Outlet', 'Test Elf', 'Test Bear']);
    const single = playOf(outlet, 'Test Outlet')!;
    expect(single.sacrificeCount).toBeUndefined();
    expect(refusal(outlet, {
      type: 'auto:activate', by: 0, card: find(outlet, 0, 'battlefield', 'Test Outlet'), abilityIndex: single.abilityIndex ?? 0,
      sacrifices: [...single.sacrificeOptions],
    })).toMatch(/does not sacrifice several/);
    // And a single sacrifice on a counted one.
    expect(refusal(altar, {
      type: 'auto:activate', by: 0, card: find(altar, 0, 'battlefield', 'Test Altar'), abilityIndex: play.abilityIndex ?? 0,
      sacrifice: play.sacrificeOptions[0]!,
    })).toMatch(/choose 2 different/);
  });
});

describe('Teferi\'s Protection: phasing, and a life total that can\'t change (D733)', () => {
  const row = (name: string, type: string, text: string, extra: Record<string, unknown> = {}) => ({
    name, type_line: type, oracle_text: text, mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', ...extra,
  });
  const ROWS = [
    row('Test Protection', 'Instant', "Until your next turn, your life total can't change and you gain protection from everything. All permanents you control phase out. (While they're phased out, they're treated as though they don't exist. They phase in before you untap during your untap step.)\nExile Test Protection."),
    row('Test Emperion', 'Artifact Creature — Golem', "Your life total can't change.", { power: '8', toughness: '8' }),
    row('Test Slip', 'Instant', 'Put a +1/+1 counter on target creature. It phases out.'),
    row('Test Blink', 'Instant', 'Target creature phases out.'),
    row('Test Watcher', 'Creature — Bird', 'When this creature enters, draw a card.', { power: '1', toughness: '1' }),
    row('Test Aura', 'Enchantment — Aura', 'Enchant creature\nEnchanted creature gets +2/+2.'),
    row('Test Drain', 'Sorcery', 'Each opponent loses 3 life. You gain 3 life.'),
    row('Test Wrath', 'Sorcery', 'Destroy all creatures.'),
    row('Test Shrine', 'Artifact', 'Pay 2 life: Draw a card.'),
    { ...row('Test Bear', 'Creature — Bear', '', { power: '2', toughness: '2' }) },
    row('Test Bolt', 'Instant', 'Test Bolt deals 3 damage to any target.'),
  ];
  const deck = customDeck({
    id: 'd733', name: 'Phasing',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Forest', count: 30 }],
    data: ROWS as never[],
  });
  const table = (opts: { hands?: Record<number, string[]>; battlefield?: Record<number, string[]>; firstSeat?: 0 | 1 }) => advanceTo(arena({
    decks: { 0: 'd733', 1: 'd733' }, deckSpecs: { d733: deck.deck },
    hands: opts.hands ?? {}, battlefield: opts.battlefield ?? {}, turn: 3, firstSeat: opts.firstSeat ?? 0,
  }), 'precombat-main');
  /** Every turn step passed with nobody attacking, until `until` holds. */
  const walk = (s0: GameState, until: (s: GameState) => boolean) => {
    let s = s0;
    for (let i = 0; i < 80 && !until(s); i++) {
      const owed = pendingDeclaration(s);
      if (owed?.kind === 'attackers') s = apply(s, { type: 'auto:attack', by: owed.seats[0]!, attackers: [] });
      else if (owed?.kind === 'blockers') s = apply(s, { type: 'auto:block', by: owed.seats[0]!, blocks: [] });
      else if (s.pendingDiscard !== null) s = drain(s);
      else s = passBoth(s);
    }
    return s;
  };
  /** Casts `name` from `seat`'s hand and resolves it. */
  const resolve = (s: GameState, seat: 0 | 1, name: string, targets?: Target[]) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: seat, card: find(s, seat, 'hand', name), ...(targets ? { targets } : {}) })));

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 4)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const reads = (text: string, type = 'Instant') => compileCard(row('Test Line', type, text, { power: '1', toughness: '1' }) as never);
    for (const [text, type] of [
      ['Target artifact, creature, or land phases out.', 'Instant'],
      ['{U}{U}: Test Line phases out.', 'Creature — Wizard'],
      ['Enchant creature\n{U}{U}: Enchanted creature phases out.', 'Enchantment — Aura'],
    ] as const) expect(reads(text, type), text).toMatchObject({ ok: true, unread: [] });
  });

  it('phases out every permanent its caster controls, with an Aura on one, and is exiled', () => {
    let s = table({ hands: { 0: ['Test Protection', 'Test Aura'] }, battlefield: { 0: ['Test Bear', 'Forest'] } });
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    const aura = find(s, 0, 'hand', 'Test Aura');
    s = resolve(s, 0, 'Test Aura', [{ kind: 'card', id: bear }]);
    s = resolve(s, 0, 'Test Protection');
    expect(ids(s, 0, 'battlefield')).toEqual([]);
    for (const id of [bear, aura]) expect(s.instances[id]!.zone).toBe('phased');
    expect(s.instances[aura]!.attachedTo).toBe(bear);
    // Both directly: the Aura is one of "all permanents you control" (CR 702.26g is for the rest).
    expect(s.instances[aura]!.phasedIndirectly).toBeUndefined();
    expect(namesIn(s, 0, 'exile')).toEqual(['Test Protection']);
    // Everybody still sees them, as phased out.
    const theirs = viewFor(s, 1);
    expect(theirs.zones['0:phased']).toEqual(expect.arrayContaining([bear, aura]));
    expect(theirs.cards[bear]?.card?.name).toBe('Test Bear');
  });

  it('keeps the life total where it is, and lets no life be paid', () => {
    let s = table({ hands: { 0: ['Test Protection'], 1: ['Test Drain'] }, battlefield: { 1: ['Test Shrine'] }, firstSeat: 1 });
    // Seat 1's turn: seat 0 casts it at instant speed after seat 1 passes priority.
    s = apply(s, { type: 'auto:pass', by: 1 });
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Protection') })));
    const life = s.seats[0]!.life;
    s = resolve(s, 1, 'Test Drain');
    expect(s.seats[0]!.life).toBe(life);
    expect(lifeLocked(s, 0)).toBe(true);
    expect(gainLife(s, 0, 5).seats[0]!.life).toBe(life);
    expect(dealDamage(s, { kind: 'player', seat: 0 }, 4, { controller: 1, source: null }).seats[0]!.life).toBe(life);
    // And the caster's opponent is not locked.
    expect(lifeLocked(s, 1)).toBe(false);
    // Protection from everything as well: the caster is not a target for the opponent's Bolt.
    const bolt = { ...s, instances: { ...s.instances } };
    const withBolt = apply(bolt, { type: 'card:move', by: 1, card: find(bolt, 1, 'library', 'Test Bolt'), toZone: 'hand' });
    const play = legalActions(withBolt, 1).plays.find((p) => p.card === find(withBolt, 1, 'hand', 'Test Bolt'));
    expect(play?.candidates.flat().some((t) => t.kind === 'player' && t.seat === 0) ?? false).toBe(false);
    expect(play?.candidates.flat().some((t) => t.kind === 'player' && t.seat === 1) ?? false).toBe(true);
  });

  it('phases them all back in at the caster\'s next untap, still attached, without entering again', () => {
    let s = table({ hands: { 0: ['Test Protection', 'Test Aura'] }, battlefield: { 0: ['Test Watcher'] } });
    const watcher = find(s, 0, 'battlefield', 'Test Watcher');
    const aura = find(s, 0, 'hand', 'Test Aura');
    s = resolve(s, 0, 'Test Aura', [{ kind: 'card', id: watcher }]);
    s = { ...s, instances: { ...s.instances, [watcher]: { ...s.instances[watcher]!, counters: { '+1/+1': 2 } } } };
    s = resolve(s, 0, 'Test Protection');
    // The opponent's whole turn: still out, and a wrath does not reach it.
    s = walk(s, (x) => x.activeSeat === 1 && x.step === 'precombat-main');
    expect(s.instances[watcher]!.zone).toBe('phased');
    const hand = ids(s, 0, 'hand').length;
    s = walk(s, (x) => x.activeSeat === 0 && x.step === 'upkeep');
    expect(s.instances[watcher]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.attachedTo).toBe(watcher);
    expect(s.instances[watcher]!.counters['+1/+1']).toBe(2);
    expect(characteristicsOf(s, s.instances[watcher]!).power).toBe(1 + 2 + 2);
    // No enter-the-battlefield draw: it never left (CR 702.26d). The draw step has not happened yet.
    expect(ids(s, 0, 'hand').length).toBe(hand);
    // And the lock and the protection are over.
    expect(lifeLocked(s, 0)).toBe(false);
  });

  it('a phased-out creature is not destroyed by a wrath, and a creature that phases out leaves combat', () => {
    let s = table({ hands: { 0: ['Test Blink'], 1: ['Test Wrath'] }, battlefield: { 0: ['Test Bear'], 1: ['Test Bear'] }, firstSeat: 1 });
    const mine = find(s, 0, 'battlefield', 'Test Bear');
    s = apply(s, { type: 'auto:pass', by: 1 });
    s = resolve(s, 0, 'Test Blink', [{ kind: 'card', id: mine }]);
    expect(s.instances[mine]!.zone).toBe('phased');
    s = resolve(s, 1, 'Test Wrath');
    expect(s.instances[mine]!.zone).toBe('phased');
    expect(namesIn(s, 1, 'graveyard')).toContain('Test Bear');
    // An attacker that phases out is out of the attack.
    let c = table({ hands: { 1: ['Test Blink'] }, battlefield: { 0: ['Test Bear'] } });
    const attacker = find(c, 0, 'battlefield', 'Test Bear');
    c = advanceTo(c, 'declare-attackers');
    c = apply(c, { type: 'auto:attack', by: 0, attackers: [{ attacker, defender: 1 }] });
    c = apply(c, { type: 'auto:pass', by: 0 });
    c = resolve(c, 1, 'Test Blink', [{ kind: 'card', id: attacker }]);
    expect(c.combat.attacks.some((a) => a.attacker === attacker)).toBe(false);
  });

  it('an Aura phases out with its creature, indirectly, and back in with it; nobody can target it meanwhile', () => {
    let s = table({ hands: { 0: ['Test Aura', 'Test Blink'], 1: ['Test Blink'] }, battlefield: { 0: ['Test Bear'] } });
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    const aura = find(s, 0, 'hand', 'Test Aura');
    s = resolve(s, 0, 'Test Aura', [{ kind: 'card', id: bear }]);
    s = resolve(s, 0, 'Test Blink', [{ kind: 'card', id: bear }]);
    expect(s.instances[bear]!.zone).toBe('phased');
    expect(s.instances[aura]!.zone).toBe('phased');
    expect(s.instances[aura]!.phasedIndirectly).toBe(true);
    // Not a target for the other Blink, which then has nothing to point at.
    s = walk(s, (x) => x.activeSeat === 1 && x.step === 'precombat-main');
    const other = legalActions(s, 1).plays.find((p) => p.card === find(s, 1, 'hand', 'Test Blink'));
    expect(other?.candidates.flat().some((t) => t.kind === 'card' && t.id === bear) ?? false).toBe(false);
    s = walk(s, (x) => x.activeSeat === 0 && x.step === 'upkeep');
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.attachedTo).toBe(bear);
    expect(s.instances[aura]!.phasedIndirectly).toBeUndefined();
    expect(characteristicsOf(s, s.instances[bear]!).power).toBe(4);
  });

  it('an opponent\'s Aura on a phased creature waits for the creature, not its own controller\'s untap', () => {
    let s = table({ hands: { 0: ['Test Blink'], 1: ['Test Aura'] }, battlefield: { 0: ['Test Bear'] }, firstSeat: 1 });
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    const aura = find(s, 1, 'hand', 'Test Aura');
    s = resolve(s, 1, 'Test Aura', [{ kind: 'card', id: bear }]);
    expect(s.instances[aura]!.attachedTo).toBe(bear);
    // Seat 0's own turn: the Bear phases out, and the Aura with it, into seat 1's keeping.
    s = walk(s, (x) => x.activeSeat === 0 && x.step === 'precombat-main');
    s = resolve(s, 0, 'Test Blink', [{ kind: 'card', id: bear }]);
    expect(s.instances[aura]!.zone).toBe('phased');
    expect(s.instances[aura]!.zoneSeat).toBe(1);
    // Seat 1's untap comes first, and the Aura stays out: it phases in with the Bear only.
    s = walk(s, (x) => x.activeSeat === 1 && x.step === 'precombat-main');
    expect(s.instances[aura]!.zone).toBe('phased');
    s = walk(s, (x) => x.activeSeat === 0 && x.step === 'upkeep');
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.zone).toBe('battlefield');
    expect(s.instances[aura]!.attachedTo).toBe(bear);
  });

  it('"it" after a target phases the target out, with its counter', () => {
    let s = table({ hands: { 0: ['Test Slip'] }, battlefield: { 0: ['Test Bear'] } });
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    s = resolve(s, 0, 'Test Slip', [{ kind: 'card', id: bear }]);
    expect(s.instances[bear]!.zone).toBe('phased');
    expect(s.instances[bear]!.counters['+1/+1']).toBe(1);
  });

  it('Platinum Emperion: damage is dealt and no life is lost, and a life cost is not offered', () => {
    const s = table({ battlefield: { 0: ['Test Emperion', 'Test Shrine'] } });
    const life = s.seats[0]!.life;
    expect(dealDamage(s, { kind: 'player', seat: 0 }, 5, { controller: 1, source: null }).seats[0]!.life).toBe(life);
    expect(loseLife(s, 0, 3).seats[0]!.life).toBe(life);
    const shrine = find(s, 0, 'battlefield', 'Test Shrine');
    expect(legalActions(s, 0).plays.some((p) => p.card === shrine)).toBe(false);
    expect(refusal(s, { type: 'auto:activate', by: 0, card: shrine, abilityIndex: 0 })).toMatch(/can't change/);
  });
});

describe('"whenever you cast an instant spell": one card type (D974)', () => {
  const ROWS = [
    { name: 'Test Mentor', type_line: 'Enchantment', oracle_text: 'Whenever you cast an instant spell, you gain 1 life.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal' },
    { name: 'Test Quick', type_line: 'Instant', oracle_text: 'Draw a card.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal' },
    { name: 'Test Slow', type_line: 'Sorcery', oracle_text: 'Draw a card.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd974', name: 'One type',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Island', count: 51 }],
    data: ROWS as never[],
  });
  const castOne = (card: string) => {
    const s = advanceTo(arena({
      decks: { 0: 'd974', 1: 'd974' }, deckSpecs: { d974: deck.deck }, hands: { 0: [card] },
      battlefield: { 0: ['Test Mentor', 'Island'], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    let t = drain(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card) } as Action), 30);
    for (let i = 0; i < 6 && t.stackOrder.length > 0; i++) t = drain(passBoth(t), 30);
    return t.seats[0]!.life - s.seats[0]!.life;
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    expect(compileCard(ROWS[0] as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('an instant gains the life; a sorcery does not', () => {
    expect(castOne('Test Quick')).toBe(1);
    expect(castOne('Test Slow')).toBe(0);
  });
});

describe('emblems: "You get an emblem with …" (D734)', () => {
  const pw = (name: string, text: string) => ({
    name, type_line: 'Legendary Planeswalker — Test', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', loyalty: '5',
  });
  const ROWS = [
    pw('Test Anthemwalker', '-1: You get an emblem with "Creatures you control get +1/+1."'),
    pw('Test Pyrowalker', '-1: You get an emblem with "Whenever you cast a spell, this emblem deals 1 damage to any target."'),
    pw('Test Handwalker', '-1: You get an emblem with "You have no maximum hand size."'),
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Opt', type_line: 'Instant', oracle_text: 'Draw a card.', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal' },
    { name: 'Test Doom', type_line: 'Instant', oracle_text: 'Destroy target planeswalker.', mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd734', name: 'Emblems',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 4 })), { name: 'Forest', count: 36 }],
    data: ROWS as never[],
  });
  const table = (opts: { hands?: Record<number, string[]>; battlefield?: Record<number, string[]> }) => advanceTo(arena({
    decks: { 0: 'd734', 1: 'd734' }, deckSpecs: { d734: deck.deck },
    hands: opts.hands ?? {}, battlefield: opts.battlefield ?? {}, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  /** Activates the walker's only ability and resolves it. */
  const ultimate = (s: GameState, name: string) => {
    const play = legalActions(s, 0).plays.find((p) => p.kind === 'activate' && p.card === find(s, 0, 'battlefield', name))!;
    return drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: play.card, abilityIndex: play.abilityIndex ?? 0 })));
  };
  const emblems = (s: GameState) => ids(s, 0, 'command').filter((id) => s.instances[id]?.emblem === true);

  it('reads an emblem whose abilities read, and leaves one that does not unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 3)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const odd = compileCard(pw('Test Oddwalker', '-1: You get an emblem with "Whenever an opponent casts their first spell each turn, counter that spell."') as never);
    expect(odd.ok && odd.unread.length).toBe(1);
    // An emblem's own ", then": one clause inside the quote, not two outside it.
    const soldiers = compileCard(pw('Test Soldierwalker', '-6: You get an emblem with "At the beginning of combat on your turn, create a 1/1 white Soldier creature token, then put a +1/+1 counter on each creature you control."') as never);
    expect(soldiers).toMatchObject({ ok: true, unread: [] });
    // And an activated ability, which nothing would offer from the command zone, stays unread.
    const tapper = compileCard(pw('Test Tapwalker', '-7: You get an emblem with "Tap an untapped artifact you control: This emblem deals 1 damage to any target."') as never);
    expect(tapper.ok && tapper.unread.length).toBe(1);
  });

  it('puts an emblem in the command zone whose anthem outlives the planeswalker and reaches later creatures', () => {
    let s = table({ hands: { 0: ['Test Bear'], 1: ['Test Doom'] }, battlefield: { 0: ['Test Anthemwalker', 'Test Bear'] } });
    const first = find(s, 0, 'battlefield', 'Test Bear');
    s = ultimate(s, 'Test Anthemwalker');
    expect(emblems(s).length).toBe(1);
    expect(characteristicsOf(s, s.instances[first]!).power).toBe(3);
    // Never cast from the command zone, and seen by everybody.
    expect(legalActions(s, 0).plays.some((p) => p.card === emblems(s)[0])).toBe(false);
    expect(viewFor(s, 1).zones['0:command']).toContain(emblems(s)[0]);
    // The walker goes; the emblem stays.
    s = apply(s, { type: 'auto:pass', by: 0 });
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 1, card: find(s, 1, 'hand', 'Test Doom'), targets: [{ kind: 'card', id: find(s, 0, 'battlefield', 'Test Anthemwalker') }] })));
    expect(namesIn(s, 0, 'graveyard')).toContain('Test Anthemwalker');
    expect(characteristicsOf(s, s.instances[first]!).power).toBe(3);
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Bear') })));
    const second = ids(s, 0, 'battlefield').find((id) => id !== first && nameOf(s, id) === 'Test Bear')!;
    expect(characteristicsOf(s, s.instances[second]!).power).toBe(3);
    // And the opponent's creatures are not its.
    expect(emblems({ ...s }).length).toBe(1);
  });

  it('an emblem\'s trigger fires from the command zone', () => {
    let s = table({ hands: { 0: ['Test Opt'] }, battlefield: { 0: ['Test Pyrowalker'] } });
    s = ultimate(s, 'Test Pyrowalker');
    const life = s.seats[1]!.life;
    s = apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Opt') });
    // The trigger asks for its target; aim it at the opponent.
    for (let i = 0; i < 6 && s.stackOrder.length > 0; i++) {
      if (s.pendingChoice !== null) { s = apply(s, { type: 'auto:choose', by: 0, targets: [{ kind: 'player', seat: 1 }] }); break; }
      s = passBoth(s);
    }
    s = drain(passBoth(s), 20);
    expect(s.seats[1]!.life).toBe(life - 1);
  });

  it('"You have no maximum hand size" from an emblem keeps a big hand through cleanup', () => {
    let s = table({ battlefield: { 0: ['Test Handwalker'] } });
    s = ultimate(s, 'Test Handwalker');
    while (ids(s, 0, 'hand').length < 10) s = apply(s, { type: 'card:move', by: 0, card: ids(s, 0, 'library')[0]!, toZone: 'hand' });
    expect(ids(s, 0, 'hand').length).toBeGreaterThan(7);
    let walked = s;
    for (let i = 0; i < 40 && !(walked.activeSeat === 1); i++) {
      const owed = pendingDeclaration(walked);
      if (owed?.kind === 'attackers') walked = apply(walked, { type: 'auto:attack', by: owed.seats[0]!, attackers: [] });
      else if (walked.pendingDiscard !== null) break;
      else walked = passBoth(walked);
    }
    expect(walked.pendingDiscard).toBeNull();
    expect(walked.activeSeat).toBe(1);
  });
});

describe('a */* from more measures: colours, zones, life, devotion (D975)', () => {
  const C = (name: string, text: string, extra: Record<string, unknown> = {}) => ({ name, type_line: 'Creature — Avatar', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '*', toughness: '*', ...extra });
  const ROWS = [
    C('Test Drove', "Test Drove's power and toughness are each equal to the number of green permanents you control."),
    C('Test Avatar', "Test Avatar's power and toughness are each equal to your life total.", { colors: ['W'] }),
    C('Test Avenger', "Test Avenger's power and toughness are each equal to 1 plus the number of artifacts your opponents control."),
    C('Test Hammer', "Test Hammer's power is equal to your devotion to red.", { mana_cost: '{2}{R}', cmc: 3, colors: ['R'], toughness: '4' }),
    C('Test Instantivore', "Test Instantivore's power and toughness are each equal to the number of instant cards in all graveyards."),
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{G}', cmc: 1, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Imp', type_line: 'Creature — Imp', oracle_text: '', mana_cost: '{R}{R}', cmc: 2, colors: ['R'], layout: 'normal', power: '1', toughness: '1' },
    { name: 'Test Relic', type_line: 'Artifact', oracle_text: '', mana_cost: '{1}', cmc: 1, colors: [], layout: 'normal' },
    { name: 'Test Bolt', type_line: 'Instant', oracle_text: 'Draw a card.', mana_cost: '{R}', cmc: 1, colors: ['R'], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd975', name: 'Stars',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 3 })), { name: 'Forest', count: 33 }],
    data: ROWS as never[],
  });
  const size = (card: string, mine: string[], theirs: string[] = [], graveyards: { 0?: string[]; 1?: string[] } = {}) => {
    const s = advanceTo(arena({
      decks: { 0: 'd975', 1: 'd975' }, deckSpecs: { d975: deck.deck },
      battlefield: { 0: [card, ...mine], 1: theirs }, graveyard: { 0: graveyards[0] ?? [], 1: graveyards[1] ?? [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const got = characteristicsOf(s, s.instances[find(s, 0, 'battlefield', card)]!);
    return `${got.power}/${got.toughness}`;
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 5)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
  });

  it('green permanents you control: itself and a green bear, not the forest', () => {
    expect(size('Test Drove', ['Test Bear', 'Forest'])).toBe('2/2');
  });

  it('your life total', () => {
    expect(size('Test Avatar', [])).toBe('20/20');
  });

  it('1 plus the artifacts your opponents control, not yours', () => {
    expect(size('Test Avenger', ['Test Relic'], ['Test Relic', 'Test Relic'])).toBe('3/3');
  });

  it('power is your devotion to red, the printed toughness stays', () => {
    expect(size('Test Hammer', ['Test Imp', 'Test Bear'])).toBe('3/4');
  });

  it('instant cards in all graveyards, both players', () => {
    expect(size('Test Instantivore', [], [], { 0: ['Test Bolt', 'Test Bear'], 1: ['Test Bolt'] })).toBe('2/2');
  });
});

describe('anthems by colour and kind: "Other green creatures you control get +1/+1" (D735)', () => {
  const C = (name: string, type: string, text: string, colors: string[], extra: Record<string, unknown> = {}) => ({
    name, type_line: type, oracle_text: text, mana_cost: '{0}', cmc: 0, colors, layout: 'normal', power: '2', toughness: '2', ...extra,
  });
  const ROWS = [
    C('Test Green Lord', 'Creature — Elf', 'Other green creatures you control get +1/+1.', ['G']),
    C('Test Forge Lord', 'Artifact Creature — Golem', 'Artifact creatures you control have flying.', []),
    C('Test Watchman', 'Creature — Human', 'Untapped creatures you control get +0/+2.', ['W']),
    C('Test Prism', 'Legendary Creature — Avatar', 'Multicolored creatures you control get +1/+0.\nLegendary creatures you control get +0/+1.', ['W', 'U']),
    C('Test Bear', 'Creature — Bear', '', ['G']),
    C('Test Goblin', 'Creature — Goblin', '', ['R']),
    C('Test Golem', 'Artifact Creature — Golem', '', []),
    C('Test Duo', 'Creature — Wizard', '', ['U', 'R']),
    C('Test Smith', 'Creature — Dwarf', 'Untapped artifact creatures you control get +1/+0.', ['R']),
  ];
  const deck = customDeck({
    id: 'd735', name: 'Anthems',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 44 }],
    data: ROWS as never[],
  });
  const table = (mine: string[], theirs: string[] = []) => advanceTo(arena({
    decks: { 0: 'd735', 1: 'd735' }, deckSpecs: { d735: deck.deck }, battlefield: { 0: mine, 1: theirs }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const size = (s: GameState, seat: 0 | 1, name: string) => {
    const ch = characteristicsOf(s, s.instances[find(s, seat, 'battlefield', name)]!);
    return `${ch.power}/${ch.toughness}`;
  };

  it('reads the family, and leaves two colours unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 4)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const two = compileCard(C('Test Line', 'Creature — Wizard', 'White and blue creatures you control get +1/+1.', ['W']) as never);
    expect(two.ok && two.unread.length).toBe(1);
  });

  it('a colour lord pumps its controller\'s other creatures of the colour, and nobody else', () => {
    const s = table(['Test Green Lord', 'Test Bear', 'Test Goblin'], ['Test Bear']);
    expect(size(s, 0, 'Test Bear')).toBe('3/3');
    expect(size(s, 0, 'Test Green Lord')).toBe('2/2');
    expect(size(s, 0, 'Test Goblin')).toBe('2/2');
    expect(size(s, 1, 'Test Bear')).toBe('2/2');
    // Made red, the Bear leaves it; made green, the Goblin joins, read live.
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    const goblin = find(s, 0, 'battlefield', 'Test Goblin');
    const swapped = pump(pump(s, [bear], bear, 1, { setColors: ['R'] }), [goblin], goblin, 1, { setColors: ['G'] });
    expect(size(swapped, 0, 'Test Bear')).toBe('2/2');
    expect(size(swapped, 0, 'Test Goblin')).toBe('3/3');
  });

  it('artifact creatures have flying, an animated or typed one included, and others do not', () => {
    const s = table(['Test Forge Lord', 'Test Golem', 'Test Bear']);
    const has = (st: GameState, name: string) => characteristicsOf(st, st.instances[find(st, 0, 'battlefield', name)]!).keywords.has('flying');
    expect(has(s, 'Test Golem')).toBe(true);
    expect(has(s, 'Test Forge Lord')).toBe(true);
    expect(has(s, 'Test Bear')).toBe(false);
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    expect(has(pump(s, [bear], bear, 0, { addTypes: ['Artifact'] }), 'Test Bear')).toBe(true);
  });

  it('untapped creatures get the bonus only while untapped', () => {
    const s = table(['Test Watchman', 'Test Bear']);
    expect(size(s, 0, 'Test Bear')).toBe('2/4');
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    const tapped = { ...s, instances: { ...s.instances, [bear]: { ...s.instances[bear]!, tapped: true } } };
    expect(size(tapped, 0, 'Test Bear')).toBe('2/2');
  });

  it('two kind words both have to hold: untapped and artifact', () => {
    const s = table(['Test Smith', 'Test Golem', 'Test Bear']);
    expect(size(s, 0, 'Test Golem')).toBe('3/2');
    expect(size(s, 0, 'Test Bear')).toBe('2/2');
    const golem = find(s, 0, 'battlefield', 'Test Golem');
    const tapped = { ...s, instances: { ...s.instances, [golem]: { ...s.instances[golem]!, tapped: true } } };
    expect(size(tapped, 0, 'Test Golem')).toBe('2/2');
  });

  it('multicolored and legendary creatures, by the colours and supertypes they have', () => {
    const s = table(['Test Prism', 'Test Duo', 'Test Goblin']);
    expect(size(s, 0, 'Test Duo')).toBe('3/2');
    expect(size(s, 0, 'Test Goblin')).toBe('2/2');
    // The Prism is both multicolored and legendary.
    expect(size(s, 0, 'Test Prism')).toBe('3/3');
  });
});

