describe('a bare X, as the X paid (D1055)', () => {
  const S = (name: string, cost: string, text: string) => ({ name, type_line: 'Sorcery', mana_cost: cost, cmc: 0, colors: ['B'], layout: 'normal', oracle_text: text });
  const ROWS = [
    S('Test Drain', '{X}', 'Target player loses X life.'),
    S('Test Grasp', '{X}', 'Test Grasp deals X damage to any target. You gain X life.'),
    S('Test Mill', '{X}', 'Target player mills X cards.'),
    S('Test Tendrils', '{0}', 'Test Tendrils deals X damage to target creature and you gain X life, where X is the number of Swamps you control.'),
    { name: 'Test Wall', type_line: 'Creature — Wall', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', power: '0', toughness: '9', oracle_text: 'Defender' },
  ];
  const deck = customDeck({ id: 'd1055', name: 'X paid', entries: [...ROWS.map((r) => ({ name: r.name, count: 4 })), { name: 'Swamp', count: 40 }], data: ROWS as never[] });
  const cast = (spell: string, target: (s: GameState) => Target, x?: number) => {
    let s = advanceTo(arena({
      decks: { 0: 'd1055', 1: 'd1055' }, deckSpecs: { d1055: deck.deck },
      battlefield: { 0: ['Swamp', 'Swamp', 'Swamp'], 1: ['Test Wall'] }, hands: { 0: [spell] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const before = s;
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [target(s)], ...(x === undefined ? {} : { x }) } as Action)), 30);
    return { before, s };
  };
  const opponent = (): Target => ({ kind: 'player', seat: 1 });

  it('reads every row whole', () => {
    for (const r of ROWS.filter((row) => row.name !== 'Test Tendrils')) {
      expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    }
  });

  it('loses, deals and gains the X paid', () => {
    const drained = cast('Test Drain', opponent, 3);
    expect(life(drained.s, 1)).toBe(life(drained.before, 1) - 3);
    const grasped = cast('Test Grasp', opponent, 2);
    expect(life(grasped.s, 1)).toBe(life(grasped.before, 1) - 2);
    expect(life(grasped.s, 0)).toBe(life(grasped.before, 0) + 2);
  });

  it('X = 0 does nothing, and X = 2 mills two', () => {
    const none = cast('Test Mill', opponent, 0);
    expect(ids(none.s, 1, 'library').length).toBe(ids(none.before, 1, 'library').length);
    const two = cast('Test Mill', opponent, 2);
    expect(ids(two.s, 1, 'library').length).toBe(ids(two.before, 1, 'library').length - 2);
  });

  /*
    The misreading this guards against: split on "and", the damage half alone would read as the
    X paid (nought on a card with no X in its cost) while the life half read the count. No reader
    takes the counted damage yet, so the honest answer is the line unread.
  */
  it('"where X is" anywhere in the sentence: no part of it reads as the X paid', () => {
    const read = compileCard(ROWS.find((row) => row.name === 'Test Tendrils') as never);
    expect(read.ok && read.unread.length).toBe(1);
    // And when the sentence is split into clauses before it is read (Sparksmith's "… and X damage to you").
    const split = compileCard({ name: 'Test Smith', type_line: 'Creature — Goblin', mana_cost: '{0}', cmc: 0, colors: ['R'], layout: 'normal', power: '1', toughness: '1',
      oracle_text: '{T}: Test Smith deals X damage to target creature and X damage to you, where X is the number of Goblins on the battlefield.' } as never);
    expect(split.ok && split.unread.length).toBe(1);
  });

  it('an X the reading would ask with ("Scry X") stays unread: the question would keep its number', () => {
    const read = compileCard({ name: 'Test Scry', type_line: 'Sorcery', mana_cost: '{X}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: 'Scry X.' } as never);
    expect(read.ok && read.unread.length).toBe(1);
    // Nor a morph cost with X in it, which turning face up neither pays nor keeps (Warbreak Trumpeter).
    const morphed = compileCard({ name: 'Test Trumpeter', type_line: 'Creature — Goblin', mana_cost: '{3}{R}', cmc: 4, colors: ['R'], layout: 'normal', power: '1', toughness: '1',
      oracle_text: 'Morph {X}{X}{R}\nWhen Test Trumpeter is turned face up, create X 1/1 red Goblin creature tokens.' } as never);
    // Both lines: the morph cost, and the trigger, whose X no mana cost pays.
    expect(morphed.ok && morphed.unread.map((u) => u.line)).toContain('Morph {X}{X}{R}');
    // Nor an X nothing pays: a sorcery with no X in its cost, an ability whose own cost has none (even
    // on a card whose mana cost does), and "+X/+X … for each" on an X spell, which is a rate.
    for (const [type, cost, text] of [
      ['Sorcery', '{B}', 'Target player loses X life.'],
      ['Artifact', '{X}{B}', 'When this artifact enters, target player loses X life.\n{T}: Target player loses X life.'],
      ['Sorcery', '{X}{G}', 'Target creature gets +X/+X until end of turn for each land you control.'],
    ]) {
      const read = compileCard({ name: 'Test Unpaid', type_line: type, mana_cost: cost, cmc: 1, colors: ['B'], layout: 'normal', oracle_text: text } as never);
      expect(read.ok && read.unread.map((u) => u.line), `${cost} ${text}`).toEqual([text.split('\n').at(-1)]);
    }
    // Nor a division whose amount is in the target spec (Fire Covenant's).
    const divided = compileCard({ name: 'Test Covenant', type_line: 'Instant', mana_cost: '{X}', cmc: 0, colors: ['R'], layout: 'normal',
      oracle_text: 'Test Covenant deals X damage divided as you choose among any number of target creatures.' } as never);
    expect(divided.ok && divided.unread.length).toBe(1);
  });
});

describe('"~ or enchanted creature deals combat damage" (D774)', () => {
  const EMISSARY = { name: "Test Emissary", type_line: 'Enchantment Creature — Crab', mana_cost: '{4}{U}', cmc: 5, colors: ['U'], layout: 'normal', power: '3', toughness: '3', oracle_text: "Bestow {5}{U}\nWhenever Test Emissary or enchanted creature deals combat damage to a player, draw a card.\nEnchanted creature gets +3/+3." };
  const OX = { name: 'Test Ox', type_line: 'Creature — Ox', mana_cost: '{1}{G}', cmc: 2, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' };
  const deck = customDeck({
    id: 'd774', name: 'Emissary',
    entries: [{ name: 'Test Emissary', count: 2 }, { name: 'Test Ox', count: 4 }, { name: 'Island', count: 54 }],
    data: [EMISSARY, OX] as never[],
  });
  const table = (mine: string[], hand: string[] = []) => advanceTo(arena({
    decks: { 0: 'd774', 1: 'd774' }, deckSpecs: { d774: deck.deck },
    hands: { 0: hand }, battlefield: { 0: mine }, turn: 2, firstSeat: 0,
  }), 'precombat-main');
  const drawsFrom = (s0: GameState, attackers: string[]) => {
    let s = advanceTo(s0, 'declare-attackers');
    const before = ids(s, 0, 'hand').length;
    s = apply(s, { type: 'auto:attack', by: 0, attackers: attackers.map((name) => ({ attacker: find(s, 0, 'battlefield', name), defender: 1 })) });
    for (let i = 0; i < 10 && s.step !== 'postcombat-main'; i++) s = drain(passBoth(s));
    return ids(s, 0, 'hand').length - before;
  };

  it('reads', () => {
    expect(compileCard(EMISSARY as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('as a creature: it draws when it connects, and an Ox beside it does not', () => {
    expect(drawsFrom(table(['Test Emissary', 'Test Ox']), ['Test Emissary', 'Test Ox'])).toBe(1);
  });

  it('bestowed: the creature it enchants draws once when it connects', () => {
    let s = table(['Island', 'Island', 'Island', 'Island', 'Island', 'Island', 'Test Ox'], ['Test Emissary']);
    s = drain(passBoth(apply(s, {
      type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Emissary'), bestowed: true,
      targets: [{ kind: 'card', id: find(s, 0, 'battlefield', 'Test Ox') }],
    })));
    expect(characteristicsOf(s, s.instances[find(s, 0, 'battlefield', 'Test Ox')]!).power).toBe(5);
    expect(drawsFrom(s, ['Test Ox'])).toBe(1);
  });
});
describe('reconfigure (D775)', () => {
  const LIZARD = { name: 'Test Lizard', type_line: 'Artifact Creature — Equipment Lizard', mana_cost: '{2}', cmc: 2, colors: [], layout: 'normal', power: '2', toughness: '2', oracle_text: 'Equipped creature gets +2/+2.\nReconfigure {2}' };
  const OX = { name: 'Test Ox', type_line: 'Creature — Ox', mana_cost: '{1}{G}', cmc: 2, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' };
  const deck = customDeck({
    id: 'd775', name: 'Reconfigure',
    entries: [{ name: 'Test Lizard', count: 2 }, { name: 'Test Ox', count: 4 }, { name: 'Forest', count: 54 }],
    data: [LIZARD, OX] as never[],
  });
  const table = () => advanceTo(arena({
    decks: { 0: 'd775', 1: 'd775' }, deckSpecs: { d775: deck.deck },
    battlefield: { 0: ['Forest', 'Forest', 'Forest', 'Forest', 'Test Lizard', 'Test Ox'] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const ch = (s: GameState, name: string) => characteristicsOf(s, s.instances[find(s, 0, 'battlefield', name)]!);
  const attach = (s: GameState) => drain(passBoth(apply(s, {
    type: 'auto:activate', by: 0, card: find(s, 0, 'battlefield', 'Test Lizard'), abilityIndex: 0,
    targets: [{ kind: 'card', id: find(s, 0, 'battlefield', 'Test Ox') }],
  })));

  it('reads, and cannot attach to itself', () => {
    expect(compileCard(LIZARD as never)).toMatchObject({ ok: true, unread: [] });
    const s = table();
    const lizard = find(s, 0, 'battlefield', 'Test Lizard');
    expect(refusal(s, { type: 'auto:activate', by: 0, card: lizard, abilityIndex: 0, targets: [{ kind: 'card', id: lizard }] })).toBeTruthy();
  });

  it('attached: the host gets the bonus and the Equipment stops being a creature', () => {
    const s = attach(table());
    expect(ch(s, 'Test Ox').power).toBe(4);
    expect(ch(s, 'Test Lizard').isCreature).toBe(false);
    expect(ch(s, 'Test Lizard').typeLine.subtypes).toEqual(['Equipment']);
  });

  it('unattached for the same cost: a creature again, and the bonus is gone', () => {
    let s = attach(table());
    const lizard = find(s, 0, 'battlefield', 'Test Lizard');
    expect(legalActions(s, 0).plays.some((p) => p.kind === 'activate' && p.card === lizard && p.abilityIndex === 1)).toBe(true);
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: lizard, abilityIndex: 1 })));
    expect(ch(s, 'Test Lizard').isCreature).toBe(true);
    expect(ch(s, 'Test Ox').power).toBe(2);
  });

  it('the unattach is not offered while it is unattached', () => {
    const s = table();
    const lizard = find(s, 0, 'battlefield', 'Test Lizard');
    expect(legalActions(s, 0).plays.some((p) => p.kind === 'activate' && p.card === lizard && p.abilityIndex === 1)).toBe(false);
  });

  it('the bot does not attach and unattach back and forth in one turn', () => {
    let s = table();
    let activations = 0;
    for (let i = 0; i < 40 && s.step === 'precombat-main'; i++) {
      const seat = s.priority ?? s.activeSeat;
      const action = botAction(s, seat as never);
      if (action === null) break;
      if (action.type === 'auto:activate' && action.card === find(s, 0, 'battlefield', 'Test Lizard')) activations += 1;
      s = drain(apply(s, action));
    }
    expect(activations).toBeLessThanOrEqual(1);
  });

  it('when the host dies, it comes unattached and is a creature again', () => {
    let s = attach(table());
    s = drain(destroy(s, find(s, 0, 'battlefield', 'Test Ox')));
    expect(ch(s, 'Test Lizard').isCreature).toBe(true);
    expect(ch(s, 'Test Lizard').power).toBe(2);
  });
});
describe('drawing X, now and owed (D1056)', () => {
  const ROWS = [
    { name: 'Test Stroke', type_line: 'Instant', mana_cost: '{X}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: 'Target player draws X cards.' },
    { name: 'Test Revelation', type_line: 'Instant', mana_cost: '{X}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: 'You gain X life and draw X cards.' },
    { name: 'Test Study', type_line: 'Sorcery', mana_cost: '{X}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: 'Draw X cards. Discard a card.' },
    { name: 'Test Drake', type_line: 'Creature — Drake', mana_cost: '{X}', cmc: 0, colors: ['U'], layout: 'normal', power: '2', toughness: '2',
      oracle_text: 'When Test Drake enters, draw X cards.' },
  ];
  const deck = customDeck({ id: 'd1056', name: 'Draw X', entries: [...ROWS.map((r) => ({ name: r.name, count: 4 })), { name: 'Island', count: 48 }], data: ROWS as never[] });
  const cast = (spell: string, x: number, target?: Target) => {
    let s = advanceTo(arena({
      decks: { 0: 'd1056', 1: 'd1056' }, deckSpecs: { d1056: deck.deck },
      battlefield: { 0: ['Island', 'Island', 'Island', 'Island'], 1: [] }, hands: { 0: [spell] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const before = s;
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), x, ...(target === undefined ? {} : { targets: [target] }) } as Action)), 30);
    return { before, s };
  };

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
  });

  it('an enters trigger draws the X its permanent was cast for', () => {
    let { before, s } = cast('Test Drake', 2);
    for (let i = 0; i < 4 && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    expect(ids(s, 0, 'hand').length).toBe(ids(before, 0, 'hand').length - 1 + 2);
  });

  it('the target draws X', () => {
    const { before, s } = cast('Test Stroke', 3, { kind: 'player', seat: 1 });
    expect(ids(s, 1, 'hand').length).toBe(ids(before, 1, 'hand').length + 3);
  });

  it('gain X and draw X, and a draw of X before a discard is in hand when the discard asks', () => {
    const rev = cast('Test Revelation', 2);
    expect(life(rev.s, 0)).toBe(life(rev.before, 0) + 2);
    expect(ids(rev.s, 0, 'hand').length).toBe(ids(rev.before, 0, 'hand').length - 1 + 2);
    // Three, not the two the reading was made with: the "now" draw is re-read with the X paid.
    const study = cast('Test Study', 3);
    // The three cards are drawn now, so the discard can choose among them.
    expect(study.s.pendingDecision?.candidates?.length).toBe(ids(study.before, 0, 'hand').length - 1 + 3);
  });
});

describe('saddle (D776)', () => {
  const STEED = { name: 'Test Steed', type_line: 'Creature — Horse Mount', mana_cost: '{1}{W}', cmc: 2, colors: ['W'], layout: 'normal', power: '2', toughness: '2', oracle_text: 'Whenever this creature attacks while saddled, it gets +2/+2 until end of turn.\nSaddle 1' };
  const OX = { name: 'Test Ox', type_line: 'Creature — Ox', mana_cost: '{1}{G}', cmc: 2, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' };
  const deck = customDeck({
    id: 'd776', name: 'Saddle',
    entries: [{ name: 'Test Steed', count: 2 }, { name: 'Test Ox', count: 4 }, { name: 'Plains', count: 54 }],
    data: [STEED, OX] as never[],
  });
  const table = () => advanceTo(arena({
    decks: { 0: 'd776', 1: 'd776' }, deckSpecs: { d776: deck.deck },
    battlefield: { 0: ['Test Steed', 'Test Ox'] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const steedOf = (s: GameState) => find(s, 0, 'battlefield', 'Test Steed');
  const saddle = (s: GameState) => drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: steedOf(s), abilityIndex: 0 })));
  const attackWithSteed = (s0: GameState) => {
    let s = advanceTo(s0, 'declare-attackers');
    s = apply(s, { type: 'auto:attack', by: 0, attackers: [{ attacker: steedOf(s), defender: 1 }] });
    return drain(passBoth(s));
  };

  it('reads', () => {
    expect(compileCard(STEED as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('saddled by tapping another creature, it gets the bonus when it attacks', () => {
    let s = saddle(table());
    expect(s.instances[find(s, 0, 'battlefield', 'Test Ox')]!.tapped).toBe(true);
    expect(s.instances[steedOf(s)]!.saddledTurn).toBe(s.turn);
    s = attackWithSteed(s);
    expect(characteristicsOf(s, s.instances[steedOf(s)]!).power).toBe(4);
  });

  it('unsaddled, the attack does nothing extra', () => {
    const s = attackWithSteed(table());
    expect(characteristicsOf(s, s.instances[steedOf(s)]!).power).toBe(2);
  });

  it('only as a sorcery, once a turn, and not into the next turn', () => {
    let s = advanceTo(arena({
      decks: { 0: 'd776', 1: 'd776' }, deckSpecs: { d776: deck.deck },
      battlefield: { 0: ['Test Steed', 'Test Ox', 'Test Ox'] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const steed = steedOf(s);
    const offered = (st: GameState) => legalActions(st, 0).plays.some((p) => p.kind === 'activate' && p.card === steed);
    expect(offered(s)).toBe(true);
    // Not in our own end step, with priority and an untapped Ox: sorcery timing.
    let late = advanceTo(s, 'declare-attackers');
    late = advanceTo(apply(late, { type: 'auto:attack', by: 0, attackers: [] }), 'end');
    expect(late.priority).toBe(0);
    expect(offered(late)).toBe(false);
    // Once a turn, though the second Ox could pay again.
    s = saddle(s);
    expect(offered(s)).toBe(false);
    // And not saddled on our next turn: the attack then gets nothing.
    s = nextTurn(nextTurn(s));
    expect(s.instances[steed]!.saddledTurn === s.turn).toBe(false);
    s = advanceTo(s, 'precombat-main');
    s = attackWithSteed(s);
    expect(characteristicsOf(s, s.instances[steed]!).power).toBe(2);
  });
});
