describe('damage to a player and each creature they control (D1059)', () => {
  const S = (name: string, cost: string, text: string) => ({ name, type_line: 'Sorcery', mana_cost: cost, cmc: 0, colors: ['R'], layout: 'normal', oracle_text: text });
  const ROWS = [
    S('Test Wave', '{0}', "Test Wave deals 4 damage to target player or planeswalker and each creature that player or that planeswalker's controller controls."),
    S('Test Fury', '{0}', "Test Fury deals 4 damage to target player or planeswalker and 1 damage to each creature that player or that planeswalker's controller controls."),
    S('Test Lava', '{X}', 'Test Lava deals X damage to target player and each creature that player controls.'),
    { name: 'Test Bear', type_line: 'Creature — Bear', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' },
    { name: 'Test Wall', type_line: 'Creature — Wall', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', power: '0', toughness: '6', oracle_text: 'Defender' },
    { name: 'Test Walker', type_line: 'Legendary Planeswalker — Test', oracle_text: '+1: Draw a card.', mana_cost: '{9}', cmc: 9, colors: ['R'], layout: 'normal', power: null, toughness: null, loyalty: '5' },
  ];
  const deck = customDeck({ id: 'd1059', name: 'Wave', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Mountain', count: 48 }], data: ROWS as never[] });
  const cast = (spell: string, aim: (s: GameState) => Target, x?: number) => {
    let s = advanceTo(arena({
      decks: { 0: 'd1059', 1: 'd1059' }, deckSpecs: { d1059: deck.deck },
      battlefield: { 0: ['Mountain', 'Mountain', 'Mountain', 'Test Bear'], 1: ['Test Bear', 'Test Wall', 'Test Walker'] }, hands: { 0: [spell] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const before = s;
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [aim(s)], ...(x === undefined ? {} : { x }) } as Action)), 30);
    return { before, s };
  };
  const player = (): Target => ({ kind: 'player', seat: 1 });

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    // A planeswalker's controller after a target that is only a player, and an X nothing pays: unread.
    for (const [cost, text] of [
      ['{0}', "Test Odd deals 4 damage to target player and each creature that player or that planeswalker's controller controls."],
      ['{0}', 'Test Odd deals X damage to target player and each creature that player controls.'],
    ]) {
      const read = compileCard({ ...ROWS[0], name: 'Test Odd', mana_cost: cost, oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it('the player and each creature they control, and not the caster\'s', () => {
    const { before, s } = cast('Test Wave', player);
    expect(life(s, 1)).toBe(life(before, 1) - 4);
    expect(namesIn(s, 1, 'battlefield')).not.toContain('Test Bear');
    expect(s.instances[find(s, 1, 'battlefield', 'Test Wall')]!.damage).toBe(4);
    expect(namesIn(s, 0, 'battlefield')).toContain('Test Bear');
  });

  it('"and 1 damage to each creature": one each', () => {
    const { s } = cast('Test Fury', player);
    expect(s.instances[find(s, 1, 'battlefield', 'Test Wall')]!.damage).toBe(1);
    expect(namesIn(s, 1, 'battlefield')).toContain('Test Bear');
  });

  it('aimed at a planeswalker: its controller\'s creatures', () => {
    const { s } = cast('Test Fury', (t) => ({ kind: 'card', id: find(t, 1, 'battlefield', 'Test Walker') }));
    expect(s.instances[find(s, 1, 'battlefield', 'Test Walker')]!.counters['loyalty']).toBe(1);
    expect(s.instances[find(s, 1, 'battlefield', 'Test Wall')]!.damage).toBe(1);
  });

  it('X is the X paid', () => {
    const { before, s } = cast('Test Lava', player, 3);
    expect(life(s, 1)).toBe(life(before, 1) - 3);
    expect(s.instances[find(s, 1, 'battlefield', 'Test Wall')]!.damage).toBe(3);
  });
});

describe('the delayed blink: back at the beginning of the next end step (D1060)', () => {
  const I = (name: string, text: string) => ({ name, type_line: 'Instant', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', oracle_text: text });
  const C = (name: string, text: string) => ({ name, type_line: 'Creature — Sphinx', mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal', power: '3', toughness: '3', oracle_text: text });
  const ROWS = [
    I('Test Void', "Exile target creature. Return it to the battlefield under its owner's control at the beginning of the next end step."),
    I('Test Borrow', 'Exile target creature. Return that card to the battlefield under your control at the beginning of the next end step.'),
    C('Test Sphinx', "{0}: Exile Test Sphinx. Return it to the battlefield under its owner's control at the beginning of the next end step."),
    { name: 'Test Bear', type_line: 'Creature — Bear', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' },
  ];
  const deck = customDeck({ id: 'd1060', name: 'Blink', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Island', count: 52 }], data: ROWS as never[] });
  // The Sphinx only where it is the subject: an untapped creature of seat 0 owes an attack declaration.
  const table = (hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1060', 1: 'd1060' }, deckSpecs: { d1060: deck.deck },
    battlefield: { 0: ['Island', ...(hand.length === 0 ? ['Test Sphinx'] : [])], 1: ['Test Bear'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [{ kind: 'card', id }] } as Action)), 30);

  it('reads every row whole, and the tapped return stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      "Exile target creature. Return it to the battlefield tapped under its owner's control at the beginning of the next end step.",
      "{0}: Exile Test Odd. Return it to the battlefield tapped under its owner's control at the beginning of the next end step.",
      // A card that left for anywhere: no reader knows where "it" is. (From the graveyard is D1061's,
      // whose delayed test is what fails if this reader takes a dies trigger.)
      "When Test Odd leaves the battlefield, return it to the battlefield under its owner's control at the beginning of the next end step.",
    ]) {
      const read = compileCard({ ...ROWS[2], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it("gone until the end step, then back under its owner's control", () => {
    let s = table(['Test Void']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Void', bear);
    expect(s.instances[bear]!.zone).toBe('exile');
    expect(s.delayed.length).toBe(1);
    s = drain(advanceTo(s, 'end'), 30);
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[bear]!.zoneSeat).toBe(1);
  });

  it('"under your control": the caster keeps it', () => {
    let s = table(['Test Borrow']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = drain(advanceTo(cast(s, 'Test Borrow', bear), 'end'), 30);
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[bear]!.zoneSeat).toBe(0);
  });

  it('a card that left exile in between is not fetched back (CR 400.7)', () => {
    let s = table(['Test Void']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Void', bear);
    s = apply(s, { type: 'card:move', by: 1, card: bear, toZone: 'hand' } as Action);
    s = drain(advanceTo(s, 'end'), 30);
    expect(s.instances[bear]!.zone).toBe('hand');
  });

  it('the self blink: the permanent exiles itself and comes back at the end step', () => {
    let s = table([]);
    const sphinx = find(s, 0, 'battlefield', 'Test Sphinx');
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: sphinx, abilityIndex: 0 } as Action)), 30);
    expect(s.instances[sphinx]!.zone).toBe('exile');
    expect(s.delayed.length).toBe(1);
    s = drain(advanceTo(s, 'end'), 30);
    expect(s.instances[sphinx]!.zone).toBe('battlefield');
    expect(s.instances[sphinx]!.zoneSeat).toBe(0);
  });

  it('a Sphinx gone before its ability resolves schedules nothing, and stays gone', () => {
    let s = table([]);
    const sphinx = find(s, 0, 'battlefield', 'Test Sphinx');
    s = apply(s, { type: 'auto:activate', by: 0, card: sphinx, abilityIndex: 0 } as Action);
    s = apply(s, { type: 'card:move', by: 0, card: sphinx, toZone: 'graveyard' } as Action);
    s = drain(passBoth(s), 30);
    expect(s.delayed.length).toBe(0);
    s = drain(advanceTo(s, 'end'), 30);
    expect(s.instances[sphinx]!.zone).toBe('graveyard');
  });
});

describe('back from the graveyard: a death trigger returns the card (D1061)', () => {
  const R = (name: string, type: string, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Demise', 'Enchantment — Aura', 'Enchant creature\nWhen enchanted creature dies, return that card to the battlefield under your control.'),
    R('Test Phoenix', 'Creature — Phoenix', "When Test Phoenix dies, return it to the battlefield tapped under its owner's control.", ['2', '2']),
    R('Test Angel', 'Creature — Angel', "Defender\nWhenever a creature an opponent controls dies, return it to the battlefield under its owner's control at the beginning of the next end step.", ['0', '4']),
    R('Test Kill', 'Instant', 'Destroy target creature.'),
    R('Test Bear', 'Creature — Bear', '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1061', name: 'Grave', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 50 }], data: ROWS as never[] });
  const table = (mine: string[], hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1061', 1: 'd1061' }, deckSpecs: { d1061: deck.deck },
    battlefield: { 0: ['Swamp', ...mine], 1: ['Test Bear'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string, id: string) =>
    passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [{ kind: 'card', id }] } as Action));

  it('reads every row whole; a tapped delayed return and a return off the battlefield stay unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      "When Test Odd dies, return it to the battlefield tapped under its owner's control at the beginning of the next end step.",
      "When Test Odd enters, return it to the battlefield under its owner's control.",
    ]) {
      const read = compileCard({ ...ROWS[1], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it("an Aura's \"that card\" is the creature that died, returned under the Aura's controller", () => {
    let s = table([], ['Test Demise', 'Test Kill']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = drain(cast(s, 'Test Demise', bear), 30);
    const aura = find(s, 0, 'battlefield', 'Test Demise');
    s = drain(cast(s, 'Test Kill', bear), 30);
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[bear]!.zoneSeat).toBe(0);
    expect(s.instances[aura]!.zone).toBe('graveyard');
  });

  it('its own death: back tapped, under its owner', () => {
    let s = table(['Test Phoenix'], ['Test Kill']);
    const phoenix = find(s, 0, 'battlefield', 'Test Phoenix');
    s = drain(cast(s, 'Test Kill', phoenix), 30);
    expect(s.instances[phoenix]!.zone).toBe('battlefield');
    expect(s.instances[phoenix]!.tapped).toBe(true);
    expect(s.instances[phoenix]!.zoneSeat).toBe(0);
  });

  it('a card exiled from the graveyard before the trigger resolves stays exiled', () => {
    let s = table(['Test Phoenix'], ['Test Kill']);
    const phoenix = find(s, 0, 'battlefield', 'Test Phoenix');
    s = cast(s, 'Test Kill', phoenix);
    expect(s.instances[phoenix]!.zone).toBe('graveyard');
    s = apply(s, { type: 'card:move', by: 0, card: phoenix, toZone: 'exile' } as Action);
    s = drain(passBoth(s), 30);
    expect(s.instances[phoenix]!.zone).toBe('exile');
  });

  it('the delayed return: in the graveyard until the end step, then back', () => {
    // The opponent's Bear, so its owner is not the Angel's controller and "its owner's" is visible.
    let s = table(['Test Angel'], ['Test Kill']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = drain(cast(s, 'Test Kill', bear), 30);
    expect(s.instances[bear]!.zone).toBe('graveyard');
    expect(s.delayed.length).toBe(1);
    s = drain(advanceTo(s, 'end'), 30);
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[bear]!.zoneSeat).toBe(1);
  });
});

describe('a quoted ability granted to a target until end of turn (D1062)', () => {
  const R = (name: string, type: string, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Stamina', 'Instant', 'Until end of turn, target creature gets +2/+0 and gains "When this creature dies, return it to the battlefield tapped under its owner\'s control."'),
    R('Test Knack', 'Instant', 'Target creature gains "{T}: You gain 3 life." until end of turn.'),
    R('Test Heirloom', 'Artifact', '{T}: Until end of turn, target creature you control gains trample and "Whenever this creature attacks, you gain 2 life."'),
    R('Test Kill', 'Instant', 'Destroy target creature.'),
    R('Test Bear', 'Creature — Bear', '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1062', name: 'Gifts', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 50 }], data: ROWS as never[] });
  const table = (mine: string[], hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1062', 1: 'd1062' }, deckSpecs: { d1062: deck.deck },
    battlefield: { 0: ['Swamp', ...mine], 1: [] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [{ kind: 'card', id }] } as Action)), 30);
  const granted = (s: GameState, card: string) => legalActions(s, 0 as SeatIndex)
    .plays.filter((play) => play.kind === 'activate' && play.card === card && play.grantedBy !== undefined);

  it('reads every row whole; a quotation with no "until end of turn", or two, stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    // A gift: the bot aims it at its own side.
    const knack = compileCard(ROWS[1] as never);
    expect(knack.ok && knack.script?.targets?.[0]?.friendly).toBe(true);
    for (const text of [
      'Target creature gains "{T}: You gain 3 life."',
      'Until end of turn, target creature gains "{T}: You gain 3 life." until end of turn.',
      // A sentence after it: the grant's table would have to ride a composition, which drops it.
      'Target creature gains "{T}: You gain 3 life." until end of turn. Draw a card.',
    ]) {
      const read = compileCard({ ...ROWS[1], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it('the pump and the dies trigger: it comes back tapped, and the pump does not', () => {
    let s = table(['Test Bear'], ['Test Stamina', 'Test Kill']);
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Stamina', bear);
    expect(power(s, bear)).toBe(4);
    s = cast(s, 'Test Kill', bear);
    expect(s.instances[bear]!.zone).toBe('battlefield');
    expect(s.instances[bear]!.tapped).toBe(true);
    // A new object (CR 400.7): the end-of-turn effect was about the one that died.
    expect(power(s, bear)).toBe(2);
  });

  it('an activated ability on the creature, gone at end of turn', () => {
    let s = table(['Test Bear'], ['Test Knack']);
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    expect(granted(s, bear)).toEqual([]);
    s = cast(s, 'Test Knack', bear);
    const play = granted(s, bear)[0]!;
    expect(play).toBeDefined();
    const before = life(s, 0);
    s = drain(passBoth(apply(s, {
      type: 'auto:activate', by: 0, card: bear, abilityIndex: play.abilityIndex ?? 0, grantedBy: play.grantedBy,
    } as Action)), 30);
    expect(life(s, 0)).toBe(before + 3);
    expect(s.instances[bear]!.tapped).toBe(true);
    s = nextTurn(s);
    expect(granted(s, bear)).toEqual([]);
  });

  it("an artifact's activated grant: trample and an attack trigger", () => {
    let s = table(['Test Bear', 'Test Heirloom'], []);
    const bear = find(s, 0, 'battlefield', 'Test Bear');
    s = drain(passBoth(apply(s, {
      type: 'auto:activate', by: 0, card: find(s, 0, 'battlefield', 'Test Heirloom'), abilityIndex: 0, targets: [{ kind: 'card', id: bear }],
    } as Action)), 30);
    expect(characteristicsOf(s, s.instances[bear]!).keywords).toContain('trample');
    expect(grantedTriggersOn(s, s.instances[bear]!)).toHaveLength(1);
  });
});

describe('"you may <a targeted action>. If you do, …" (D1063)', () => {
  const C = (name: string, text: string) => ({
    name, type_line: 'Creature — Spirit', oracle_text: text, mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', power: '1', toughness: '1',
  });
  const ROWS = [
    C('Test Wisp', "When Test Wisp enters, you may exile target creature. If you do, return that card to the battlefield under its owner's control at the beginning of the next end step."),
    C('Test Imp', 'When Test Imp enters, you may exile target creature card from a graveyard. If you do, you gain 2 life.'),
    C('Test Tapper', 'When Test Tapper enters, you may tap target creature. If you do, you gain 2 life.'),
    C('Test Teller', 'When Test Teller enters, you may put target enchantment card from your graveyard on top of your library. If you do, you gain life equal to its mana value.'),
    { name: 'Test Bear', type_line: 'Creature — Bear', oracle_text: '', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', power: '2', toughness: '2' },
    { name: 'Test Charm', type_line: 'Enchantment', oracle_text: '', mana_cost: '{3}', cmc: 3, colors: ['G'], layout: 'normal' },
  ];
  const deck = customDeck({
    id: 'd1063', name: 'If you do',
    entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Plains', count: 48 }],
    data: ROWS as never[],
  });
  const table = (card: string) => advanceTo(arena({
    decks: { 0: 'd1063', 1: 'd1063' }, deckSpecs: { d1063: deck.deck },
    battlefield: { 0: ['Plains'], 1: ['Test Bear'] }, hands: { 0: [card] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  /** `card` cast and its arrival trigger aimed at `aim`, up to the yes-or-no. */
  const enter = (s0: GameState, card: string, aim: (s: GameState) => string) => {
    let s = passBoth(apply(s0, { type: 'auto:cast', by: 0, card: find(s0, 0, 'hand', card) } as Action));
    if (s.pendingChoice !== null) s = apply(s, { type: 'auto:choose', by: 0, targets: [{ kind: 'card', id: aim(s) }] } as Action);
    for (let i = 0; i < 8 && s.pendingDecision === null && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    return s;
  };
  const say = (s: GameState, yes: boolean) => {
    expect(s.pendingDecision).not.toBeNull();
    const no = (s.pendingDecision?.options ?? []).find((o) => o !== 'Yes')!;
    let next = drain(apply(s, { type: 'auto:decide', by: 0, cards: [], option: yes ? 'Yes' : no } as Action), 30);
    for (let i = 0; i < 6 && next.stackOrder.length > 0; i++) next = drain(passBoth(next), 30);
    return next;
  };
  const theirBear = (s: GameState) => find(s, 1, 'battlefield', 'Test Bear');

  it('reads every row whole; a second half that does not read keeps the line unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const row of ROWS.slice(0, 4)) expect(compileCard(row as never), row.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      "When Test Odd enters, you may exile target creature. If you do, return that card to the battlefield tapped under its owner's control at the beginning of the next end step.",
      // A question after the yes: the order of the two could not be stated.
      'When Test Odd enters, you may tap target creature. If you do, discard a card.',
    ]) {
      const odd = compileCard(C('Test Odd', text) as never);
      expect(odd.ok && odd.unread.length, text).toBe(1);
    }
    // The targets are the composition's, which knows the pair is a blink (D543).
    const wisp = compileCard(ROWS[0] as never);
    expect(wisp.ok && wisp.script?.triggers?.[0]?.targets?.[0]?.blinks).toBe(true);
  });

  it('yes: exiled now, back under its owner at the end step; no: nothing happens', () => {
    const s = enter(table('Test Wisp'), 'Test Wisp', theirBear);
    const bear = theirBear(s);
    let yes = say(s, true);
    expect(yes.instances[bear]!.zone).toBe('exile');
    expect(yes.delayed.length).toBe(1);
    yes = drain(advanceTo(yes, 'end'), 30);
    expect(yes.instances[bear]!.zone).toBe('battlefield');
    expect(yes.instances[bear]!.zoneSeat).toBe(1);
    const no = say(s, false);
    expect(no.instances[bear]!.zone).toBe('battlefield');
    expect(no.delayed.length).toBe(0);
  });

  it('a card out of a graveyard, and the life after it', () => {
    let s = table('Test Imp');
    const bear = theirBear(s);
    s = apply(s, { type: 'card:move', by: 1, card: bear, toZone: 'graveyard' } as Action);
    s = enter(s, 'Test Imp', () => bear);
    const before = life(s, 0);
    const yes = say(s, true);
    expect(yes.instances[bear]!.zone).toBe('exile');
    expect(life(yes, 0)).toBe(before + 2);
  });

  it('"if you do" is whether it happened: tapping a creature already tapped gains nothing', () => {
    let s = table('Test Tapper');
    s = apply(s, { type: 'card:tap', by: 1, card: theirBear(s) } as Action);
    expect(s.instances[theirBear(s)]!.tapped).toBe(true);
    s = enter(s, 'Test Tapper', theirBear);
    const before = life(s, 0);
    expect(life(say(s, true), 0)).toBe(before);
  });

  it('"its mana value" is the card the first half moved', () => {
    let s = table('Test Teller');
    s = apply(s, { type: 'card:move', by: 0, card: find(s, 0, 'library', 'Test Charm'), toZone: 'graveyard' } as Action);
    const charm = find(s, 0, 'graveyard', 'Test Charm');
    s = enter(s, 'Test Teller', () => charm);
    const before = life(s, 0);
    const yes = say(s, true);
    expect(yes.instances[charm]!.zone).toBe('library');
    expect(life(yes, 0)).toBe(before + 3);
  });
});

describe('"target … you own" (D1064)', () => {
  const R = (name: string, type: string, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Grasp', 'Instant', 'Return target creature you own to your hand.'),
    R('Test Stylus', 'Artifact', '{T}: Put target permanent you own on the bottom of your library.'),
    R('Test Bear', 'Creature — Bear', '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1064', name: 'Owned', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Island', count: 54 }], data: ROWS as never[] });
  const table = (hand: string[], mine: string[] = []) => advanceTo(arena({
    decks: { 0: 'd1064', 1: 'd1064' }, deckSpecs: { d1064: deck.deck },
    battlefield: { 0: ['Island', 'Test Bear', ...mine], 1: ['Test Bear'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const castAt = (s: GameState, id: string): Action => ({ type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Grasp'), targets: [{ kind: 'card', id }] } as Action);

  it('reads every row whole; "to your hand" on a target anyone may own stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    // And "you own" on something that is not a permanent: a spell is owned too, and is not read here.
    for (const text of ['Return target creature to your hand.', 'Put target creature on the bottom of your library.', 'Counter target spell you own.']) {
      const read = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it('ownership, not control: a creature you own that they took, yes; one you took, no', () => {
    let s = table(['Test Grasp']);
    const mine = find(s, 0, 'battlefield', 'Test Bear');
    const theirs = find(s, 1, 'battlefield', 'Test Bear');
    expect(refusal(s, castAt(s, theirs))).not.toBeNull();
    s = gainControl(gainControl(s, mine, 1), theirs, 0);
    expect(refusal(s, castAt(s, theirs))).not.toBeNull();
    expect(refusal(s, castAt(s, mine))).toBeNull();
    s = drain(passBoth(apply(s, castAt(s, mine))), 30);
    expect(s.instances[mine]!.zone).toBe('hand');
    expect(s.instances[mine]!.zoneSeat).toBe(0);
  });

  it('the bottom of your library, for a permanent you own', () => {
    let s = table([], ['Test Stylus']);
    const mine = find(s, 0, 'battlefield', 'Test Bear');
    s = drain(passBoth(apply(s, {
      type: 'auto:activate', by: 0, card: find(s, 0, 'battlefield', 'Test Stylus'), abilityIndex: 0, targets: [{ kind: 'card', id: mine }],
    } as Action)), 30);
    expect(s.instances[mine]!.zone).toBe('library');
    const library = ids(s, 0, 'library');
    expect(library[library.length - 1]).toBe(mine);
  });
});

describe('a quoted ability granted to the team until end of turn (D1065)', () => {
  const R = (name: string, type: string, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['R'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Volley', 'Instant', 'Until end of turn, creatures you control get +1/+0 and gain "{T}: You gain 1 life."'),
    R('Test Brawl', 'Instant', 'Until end of turn, all creatures gain "{T}: You gain 1 life."'),
    R('Test Bear', 'Creature — Bear', '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1065', name: 'Team gifts', entries: [...ROWS.map((r) => ({ name: r.name, count: r.name === 'Test Bear' ? 4 : 2 })), { name: 'Mountain', count: 52 }], data: ROWS as never[] });
  const table = (hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1065', 1: 'd1065' }, deckSpecs: { d1065: deck.deck },
    battlefield: { 0: ['Mountain', 'Test Bear', 'Test Bear'], 1: ['Test Bear'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell) } as Action)), 30);
  // What the creature has, whoever holds priority: an opponent without it is offered nothing.
  const granted = (s: GameState, _seat: SeatIndex, card: string) => grantedAbilitiesOn(s, s.instances[card]!);

  it('reads every row whole; a team narrowed by a type stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      'Until end of turn, Goblin creatures you control gain "{T}: You gain 1 life."',
      // No duration: not a grant for the turn, and not this reader's.
      'Creatures you control gain "{T}: You gain 1 life."',
    ]) {
      const odd = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: text } as never);
      expect(odd.ok && odd.unread.length, text).toBe(1);
    }
  });

  it('your creatures on the battlefield as it resolves, and not the opponent\'s, nor one that arrives later', () => {
    let s = table(['Test Volley']);
    const [a, b] = ids(s, 0, 'battlefield').filter((id) => nameOf(s, id) === 'Test Bear');
    const theirs = find(s, 1, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Volley');
    expect(granted(s, 0, a!)).toHaveLength(1);
    expect(granted(s, 0, b!)).toHaveLength(1);
    expect(power(s, a!)).toBe(3);
    expect(granted(s, 1, theirs)).toEqual([]);
    const late = find(s, 0, 'library', 'Test Bear');
    s = apply(s, { type: 'card:move', by: 0, card: late, toZone: 'battlefield' } as Action);
    expect(granted(s, 0, late)).toEqual([]);
  });

  it('"all creatures": the opponent\'s too', () => {
    let s = table(['Test Brawl']);
    const theirs = find(s, 1, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Brawl');
    expect(granted(s, 1, theirs)).toHaveLength(1);
  });
});

describe('a new body for the turn: base size, lost abilities, a new type (D1066)', () => {
  const R = (name: string, type: string, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['U'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Humble', 'Instant', 'Until end of turn, target creature loses all abilities and has base power and toughness 0/1.'),
    R('Test Polymorph', 'Instant', 'Until end of turn, target creature becomes a Dragon with base power and toughness 4/4 and gains trample.'),
    R('Test Grower', 'Instant', 'Target creature has base power and toughness 5/5 until end of turn.'),
    R('Test Giant', 'Instant', 'Target creature gets +3/+3 until end of turn.'),
    R('Test Knight', 'Creature — Human Knight', 'Flying', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1066', name: 'Bodies', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Island', count: 50 }], data: ROWS as never[] });
  const table = (hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1066', 1: 'd1066' }, deckSpecs: { d1066: deck.deck },
    battlefield: { 0: ['Island'], 1: ['Test Knight'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [{ kind: 'card', id }] } as Action)), 30);
  const knight = (s: GameState) => find(s, 1, 'battlefield', 'Test Knight');
  const body = (s: GameState) => characteristicsOf(s, s.instances[knight(s)]!);

  it('reads every row whole; no duration, or a type that is not one, stays unread; small is hostile, big a gift', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 4)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      'Target creature has base power and toughness 0/1.',
      'Until end of turn, target creature becomes a Glorp with base power and toughness 4/4.',
    ]) {
      const read = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
    const humble = compileCard(ROWS[0] as never);
    expect(humble.ok && humble.script?.removesACreature).toBe(true);
    expect(humble.ok && humble.script?.targets?.[0]?.friendly).toBeUndefined();
    // Small is hostile even with its abilities kept (Diminish).
    const diminish = compileCard({ ...ROWS[2], name: 'Test Diminish', oracle_text: 'Target creature has base power and toughness 1/1 until end of turn.' } as never);
    expect(diminish.ok && diminish.script?.removesACreature).toBe(true);
    // Setting nothing, it is the pump readers' sentence, with their hints: hexproof protects.
    const shield = compileCard({ ...ROWS[2], name: 'Test Shield', oracle_text: 'Target creature gains hexproof until end of turn.' } as never);
    expect(shield.ok && shield.script?.protectsACreature).toBe(true);
    const grower = compileCard(ROWS[2] as never);
    expect(grower.ok && grower.script?.removesACreature).toBeUndefined();
    expect(grower.ok && grower.script?.targets?.[0]?.friendly).toBe(true);
  });

  it('a 0/1 with nothing, until the turn ends', () => {
    let s = table(['Test Humble']);
    s = cast(s, 'Test Humble', knight(s));
    expect([body(s).power, body(s).toughness]).toEqual([0, 1]);
    expect(body(s).keywords.has('flying')).toBe(false);
    s = nextTurn(s);
    expect([body(s).power, body(s).toughness]).toEqual([2, 2]);
    expect(body(s).keywords.has('flying')).toBe(true);
  });

  it('a Giant Growth before it still counts on top (layer 7c over 7b)', () => {
    let s = table(['Test Giant', 'Test Humble']);
    s = cast(s, 'Test Giant', knight(s));
    s = cast(s, 'Test Humble', knight(s));
    expect([body(s).power, body(s).toughness]).toEqual([3, 4]);
  });

  it('a Dragon and nothing else, 4/4 with trample', () => {
    let s = table(['Test Polymorph']);
    s = cast(s, 'Test Polymorph', knight(s));
    expect([body(s).power, body(s).toughness]).toEqual([4, 4]);
    expect(body(s).typeLine.subtypes).toEqual(['Dragon']);
    expect(body(s).keywords.has('trample')).toBe(true);
  });

  it('base 5/5 for a gift', () => {
    let s = table(['Test Grower']);
    s = cast(s, 'Test Grower', knight(s));
    expect([body(s).power, body(s).toughness]).toEqual([5, 5]);
  });
});

describe('a new body for itself (D1067)', () => {
  const C = (name: string, text: string, pt: [string, string]) => ({
    name, type_line: 'Creature — Human Knight', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: text, power: pt[0], toughness: pt[1],
  });
  const ROWS = [
    C('Test Initiate', '{0}: Test Initiate has base power and toughness 5/5 until end of turn.', ['1', '1']),
    C('Test Drake Knight', '{0}: Until end of turn, Test Drake Knight becomes a Dragon, gets +1/+1, and gains flying.', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1067', name: 'Own bodies', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 56 }], data: ROWS as never[] });
  const table = (card: string) => advanceTo(arena({
    decks: { 0: 'd1067', 1: 'd1067' }, deckSpecs: { d1067: deck.deck },
    battlefield: { 0: ['Forest', card], 1: [] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const use = (s: GameState, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: id, abilityIndex: 0 } as Action)), 30);

  it('reads every row whole; no duration stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      '{0}: Test Odd has base power and toughness 5/5.',
      // From the graveyard an end-of-turn body means nothing.
      'When Test Odd dies, Test Odd has base power and toughness 5/5 until end of turn.',
    ]) {
      const odd = compileCard(C('Test Odd', text, ['1', '1']) as never);
      expect(odd.ok && odd.unread.length, text).toBe(1);
    }
  });

  it('5/5 until the turn ends, then 1/1 again', () => {
    let s = table('Test Initiate');
    const id = find(s, 0, 'battlefield', 'Test Initiate');
    s = use(s, id);
    expect([power(s, id), characteristicsOf(s, s.instances[id]!).toughness]).toEqual([5, 5]);
    s = nextTurn(s);
    expect(power(s, id)).toBe(1);
  });

  it('gone before it resolves: the card that comes back is a new object, and a 1/1', () => {
    let s = table('Test Initiate');
    const id = find(s, 0, 'battlefield', 'Test Initiate');
    s = apply(s, { type: 'auto:activate', by: 0, card: id, abilityIndex: 0 } as Action);
    s = apply(s, { type: 'card:move', by: 0, card: id, toZone: 'hand' } as Action);
    s = drain(passBoth(s), 30);
    s = apply(s, { type: 'card:move', by: 0, card: id, toZone: 'battlefield' } as Action);
    expect(power(s, id)).toBe(1);
  });

  it('a Dragon, one bigger, with flying', () => {
    let s = table('Test Drake Knight');
    const id = find(s, 0, 'battlefield', 'Test Drake Knight');
    s = use(s, id);
    const ch = characteristicsOf(s, s.instances[id]!);
    expect([ch.power, ch.toughness]).toEqual([3, 3]);
    expect(ch.typeLine.subtypes).toEqual(['Dragon']);
    expect(ch.keywords.has('flying')).toBe(true);
  });
});

describe('an artifact that animates itself (D1068)', () => {
  const A = (name: string, text: string) => ({ name, type_line: 'Artifact', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', oracle_text: text });
  const ROWS = [
    A('Test Keyrune', '{0}: Test Keyrune becomes a 2/2 white and blue Bird artifact creature with flying until end of turn.'),
    A('Test Idol', '{0}: Until end of turn, Test Idol becomes a 3/3 Golem artifact creature.'),
  ];
  const deck = customDeck({ id: 'd1068', name: 'Keyrunes', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Plains', count: 56 }], data: ROWS as never[] });
  const table = (card: string) => advanceTo(arena({
    decks: { 0: 'd1068', 1: 'd1068' }, deckSpecs: { d1068: deck.deck },
    battlefield: { 0: ['Plains', card], 1: [] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const use = (s: GameState, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: id, abilityIndex: 0 } as Action)), 30);

  it('reads every row whole; a target, or a creature that is not an artifact creature, stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      '{0}: Until end of turn, target noncreature artifact you control becomes a 4/4 artifact creature.',
      '{0}: Test Odd becomes a 2/2 Bird creature until end of turn.',
    ]) {
      const read = compileCard(A('Test Odd', text) as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it('a 2/2 white and blue Bird artifact creature with flying, until the turn ends', () => {
    let s = table('Test Keyrune');
    const id = find(s, 0, 'battlefield', 'Test Keyrune');
    s = use(s, id);
    const ch = characteristicsOf(s, s.instances[id]!);
    expect(ch.isCreature).toBe(true);
    expect([ch.power, ch.toughness]).toEqual([2, 2]);
    expect(ch.typeLine.types).toEqual(expect.arrayContaining(['Artifact', 'Creature']));
    expect(ch.typeLine.subtypes).toContain('Bird');
    expect(ch.colors).toEqual(expect.arrayContaining(['W', 'U']));
    expect(ch.keywords.has('flying')).toBe(true);
    s = nextTurn(s);
    expect(characteristicsOf(s, s.instances[id]!).isCreature).toBe(false);
  });

  it('"until end of turn" first reads the same', () => {
    let s = table('Test Idol');
    const id = find(s, 0, 'battlefield', 'Test Idol');
    s = use(s, id);
    expect(power(s, id)).toBe(3);
    expect(characteristicsOf(s, s.instances[id]!).typeLine.subtypes).toEqual(['Golem']);
  });
});

describe("damage to that land's controller (D1069)", () => {
  const ROWS = [
    { name: 'Test Ankh', type_line: 'Artifact', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', oracle_text: "Whenever a land enters, Test Ankh deals 2 damage to that land's controller." },
    { name: 'Test Insolence', type_line: 'Enchantment — Aura', mana_cost: '{0}', cmc: 0, colors: ['R'], layout: 'normal', oracle_text: "Enchant creature\nWhenever enchanted creature becomes tapped, Test Insolence deals 2 damage to that creature's controller." },
    { name: 'Test Bear', type_line: 'Creature — Bear', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: '', power: '2', toughness: '2' },
  ];
  const deck = customDeck({ id: 'd1069', name: 'Punisher', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Mountain', count: 54 }], data: ROWS as never[] });
  const table = (mine: string[], hand: string[], theirHand: string[] = []) => advanceTo(arena({
    decks: { 0: 'd1069', 1: 'd1069' }, deckSpecs: { d1069: deck.deck },
    battlefield: { 0: ['Mountain', ...mine], 1: ['Test Bear'] }, hands: { 0: hand, 1: theirHand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const settle = (s: GameState) => {
    let next = s;
    for (let i = 0; i < 6 && next.stackOrder.length > 0; i++) next = drain(passBoth(next), 30);
    return next;
  };

  it('reads every row whole; the card\'s own entry stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const text of [
      "When Test Odd enters, Test Odd deals 2 damage to that creature's controller.",
    ]) {
      const read = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: text } as never);
      expect(read.ok && read.unread.length, text).toBe(1);
    }
  });

  it("whoever's land it is takes the damage", () => {
    let s = table(['Test Ankh'], ['Mountain'], ['Mountain']);
    const mine = life(s, 0);
    const theirs = life(s, 1);
    s = settle(apply(s, { type: 'auto:playLand', by: 0, card: find(s, 0, 'hand', 'Mountain') } as Action));
    expect(life(s, 0)).toBe(mine - 2);
    expect(life(s, 1)).toBe(theirs);
    s = advanceTo(nextTurn(s), 'precombat-main');
    s = settle(apply(s, { type: 'auto:playLand', by: 1, card: find(s, 1, 'hand', 'Mountain') } as Action));
    expect(life(s, 1)).toBe(theirs - 2);
  });

  it("the enchanted creature's controller, when it becomes tapped", () => {
    let s = table([], ['Test Insolence']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Insolence'), targets: [{ kind: 'card', id: bear }] } as Action)), 30);
    const theirs = life(s, 1);
    const mine = life(s, 0);
    s = advanceTo(nextTurn(s), 'declare-attackers');
    s = settle(apply(s, { type: 'auto:attack', by: 1, attackers: [{ attacker: bear, defender: 0 }] } as Action));
    expect(s.instances[bear]!.tapped).toBe(true);
    expect(life(s, 1)).toBe(theirs - 2);
    expect(life(s, 0)).toBe(mine);
  });
});

describe('"whenever a creature blocks" (D1070)', () => {
  const E = (name: string, text: string) => ({ name, type_line: 'Enchantment', mana_cost: '{0}', cmc: 0, colors: ['R'], layout: 'normal', oracle_text: text });
  const ROWS = [
    E('Test Strain', "Whenever a creature blocks, Test Strain deals 1 damage to that creature's controller."),
    E('Test Guard', 'Whenever a creature you control blocks, you gain 2 life.'),
    E('Test Watch', 'Whenever a creature an opponent controls blocks, you gain 1 life.'),
    { name: 'Test Sentry', type_line: 'Creature — Soldier', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', oracle_text: 'Whenever another creature you control blocks, you gain 3 life.', power: '2', toughness: '2' },
    { name: 'Test Bear', type_line: 'Creature — Bear', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: '', power: '2', toughness: '2' },
  ];
  const deck = customDeck({ id: 'd1070', name: 'Blocks', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Mountain', count: 52 }], data: ROWS as never[] });

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 4)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
  });

  it('"another": the watcher blocking is not another creature', () => {
    let s = advanceTo(arena({
      decks: { 0: 'd1070', 1: 'd1070' }, deckSpecs: { d1070: deck.deck },
      battlefield: { 0: ['Test Bear'], 1: ['Test Sentry'] }, turn: 3, firstSeat: 0,
    }), 'declare-attackers');
    const theirs = life(s, 1);
    const attacker = find(s, 0, 'battlefield', 'Test Bear');
    const blocker = find(s, 1, 'battlefield', 'Test Sentry');
    s = passBoth(apply(s, { type: 'auto:attack', by: 0, attackers: [{ attacker, defender: 1 }] } as Action));
    s = apply(s, { type: 'auto:block', by: 1, blocks: [{ blocker, attacker }] } as Action);
    for (let i = 0; i < 10 && s.step !== 'postcombat-main'; i++) s = drain(passBoth(s), 30);
    expect(life(s, 1)).toBe(theirs);
  });

  it("the blocker's controller takes the damage; whose creature it is decides who gains", () => {
    let s = advanceTo(arena({
      decks: { 0: 'd1070', 1: 'd1070' }, deckSpecs: { d1070: deck.deck },
      battlefield: { 0: ['Test Bear', 'Test Strain', 'Test Watch'], 1: ['Test Bear', 'Test Guard', 'Test Watch'] },
      turn: 3, firstSeat: 0,
    }), 'declare-attackers');
    const mine = life(s, 0);
    const theirs = life(s, 1);
    const attacker = find(s, 0, 'battlefield', 'Test Bear');
    const blocker = find(s, 1, 'battlefield', 'Test Bear');
    s = passBoth(apply(s, { type: 'auto:attack', by: 0, attackers: [{ attacker, defender: 1 }] } as Action));
    s = apply(s, { type: 'auto:block', by: 1, blocks: [{ blocker, attacker }] } as Action);
    for (let i = 0; i < 10 && s.step !== 'postcombat-main'; i++) s = drain(passBoth(s), 30);
    // Seat 1's blocker: Strain deals 1 to seat 1, its own Guard gains it 2; seat 0's Watch gains 1.
    // Seat 1's Watch hears nothing, because the blocker is not an opponent's creature to it.
    expect(life(s, 1)).toBe(theirs - 1 + 2);
    expect(life(s, 0)).toBe(mine + 1);
  });
});

describe('clash with an opponent (D1071)', () => {
  const R = (name: string, type: string, cost: string, cmc: number, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: cost, cmc, colors: ['R'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Clasher', 'Creature — Goblin', '{0}', 0, 'When Test Clasher enters, clash with an opponent. If you win, put a +1/+1 counter on Test Clasher.', ['2', '2']),
    R('Test Lash', 'Instant', '{0}', 0, "Test Lash deals 3 damage to target creature. Clash with an opponent. If you win, Test Lash deals 3 damage to that creature's controller."),
    R('Test Wager', 'Sorcery', '{0}', 0, 'Clash with an opponent. If you win, draw two cards. Otherwise, you lose 2 life.'),
    R('Test Giant', 'Creature — Giant', '{6}', 6, '', ['6', '6']),
    R('Test Pebble', 'Artifact', '{0}', 0, ''),
    R('Test Bear', 'Creature — Bear', '{0}', 0, '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1071', name: 'Clash', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Mountain', count: 48 }], data: ROWS as never[] });
  /** Seat 0's top card is `mine`, seat 1's is `theirs`. */
  const table = (hand: string, mine: string, theirs: string) => {
    let s = advanceTo(arena({
      decks: { 0: 'd1071', 1: 'd1071' }, deckSpecs: { d1071: deck.deck },
      battlefield: { 0: ['Mountain'], 1: ['Test Bear'] }, hands: { 0: [hand] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    s = putOnTopOfLibrary(s, find(s, 0, 'library', mine));
    s = putOnTopOfLibrary(s, find(s, 1, 'library', theirs));
    return s;
  };
  const top = (s: GameState, seat: SeatIndex) => nameOf(s, ids(s, seat, 'library')[0]!);
  /** Both keep-or-bottom questions answered, mine then theirs, then the stack emptied. */
  const answer = (s0: GameState, mine: boolean, theirs: boolean) => {
    let s = s0;
    for (let i = 0; i < 8 && s.pendingDecision === null && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    for (const [seat, bottom] of [[0, mine], [1, theirs]] as const) {
      expect(s.pendingDecision?.seat).toBe(seat);
      s = drain(apply(s, { type: 'auto:decide', by: seat, cards: [], option: bottom ? 'Put it on the bottom' : 'Keep it on top' } as Action), 30);
    }
    for (let i = 0; i < 6 && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    return s;
  };
  const cast = (s: GameState, card: string, targets: Target[] = []) =>
    passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card), targets } as Action));

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 3)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    // An outcome that asks a question of its own: refused, not read without it.
    // And two outcomes that each aim at something: one target list cannot hold both choices.
    for (const text of [
      'Clash with an opponent. If you win, discard a card.',
      'Clash with an opponent. If you win, destroy target artifact. Otherwise, destroy target creature.',
    ]) {
      const odd = compileCard(R('Test Odd', 'Sorcery', '{0}', 0, text) as never);
      expect(odd.ok && odd.unread.length, text).toBe(1);
    }
  });

  it('the greater mana value wins: a counter, and each card stays or goes to the bottom as chosen', () => {
    const s = answer(cast(table('Test Clasher', 'Test Giant', 'Test Pebble'), 'Test Clasher'), true, false);
    const clasher = find(s, 0, 'battlefield', 'Test Clasher');
    expect(s.instances[clasher]!.counters['+1/+1']).toBe(1);
    expect(top(s, 0)).not.toBe('Test Giant');
    expect(nameOf(s, ids(s, 0, 'library').at(-1)!)).toBe('Test Giant');
    expect(top(s, 1)).toBe('Test Pebble');
  });

  it('the lesser, and a tie, lose', () => {
    let s = answer(cast(table('Test Clasher', 'Test Pebble', 'Test Giant'), 'Test Clasher'), false, false);
    expect(s.instances[find(s, 0, 'battlefield', 'Test Clasher')]!.counters['+1/+1'] ?? 0).toBe(0);
    s = answer(cast(table('Test Clasher', 'Test Giant', 'Test Giant'), 'Test Clasher'), false, false);
    expect(s.instances[find(s, 0, 'battlefield', 'Test Clasher')]!.counters['+1/+1'] ?? 0).toBe(0);
  });

  it('"otherwise": the losing outcome', () => {
    let s = table('Test Wager', 'Test Pebble', 'Test Giant');
    const before = life(s, 0);
    s = answer(cast(s, 'Test Wager'), false, false);
    expect(life(s, 0)).toBe(before - 2);
  });

  it("a target before the clash, and \"that creature's controller\" after a win", () => {
    let s = table('Test Lash', 'Test Giant', 'Test Pebble');
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    const theirs = life(s, 1);
    s = answer(cast(s, 'Test Lash', [{ kind: 'card', id: bear }]), false, false);
    expect(s.instances[bear]!.zone).toBe('graveyard');
    expect(life(s, 1)).toBe(theirs - 3);
  });
});

describe('kinship (D1072)', () => {
  const C = (name: string, type: string, text: string) => ({
    name, type_line: type, mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', oracle_text: text, power: '1', toughness: '1',
  });
  const ROWS = [
    C('Test Schemer', 'Creature — Faerie Rogue', 'Kinship — At the beginning of your upkeep, you may look at the top card of your library. If it shares a creature type with Test Schemer, you may reveal it. If you do, each opponent loses 2 life.'),
    C('Test Sprite', 'Creature — Faerie', ''),
    C('Test Shifter', 'Creature — Shapeshifter', 'Changeling'),
    C('Test Bear', 'Creature — Bear', ''),
  ];
  const deck = customDeck({ id: 'd1072', name: 'Kin', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 52 }], data: ROWS as never[] });
  /** The Schemer out, `top` on top of seat 0's library, at the start of seat 0's turn. */
  const upkeep = (top: string) => {
    let s = arena({
      decks: { 0: 'd1072', 1: 'd1072' }, deckSpecs: { d1072: deck.deck },
      battlefield: { 0: ['Swamp', 'Test Schemer'], 1: [] }, turn: 2, firstSeat: 1,
    });
    s = putOnTopOfLibrary(s, find(s, 0, 'library', top));
    s = advanceTo(nextTurn(s), 'upkeep');
    for (let i = 0; i < 6 && s.pendingDecision === null && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    return s;
  };
  const finish = (s0: GameState) => {
    let s = s0;
    for (let i = 0; i < 6 && s.stackOrder.length > 0; i++) s = drain(passBoth(s), 30);
    return s;
  };

  it('reads whole', () => {
    expect(deck.unknown).toEqual([]);
    expect(compileCard(ROWS[0] as never)).toMatchObject({ ok: true, unread: [] });
    // A payoff that aims or asks: the reveal is answered as the ability resolves, after targets.
    for (const payoff of ['target creature gets -1/-1 until end of turn', 'discard a card']) {
      const text = `Kinship — At the beginning of your upkeep, you may look at the top card of your library. If it shares a creature type with Test Odd, you may reveal it. If you do, ${payoff}.`;
      const odd = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: text } as never);
      expect(odd.ok && odd.unread.length, payoff).toBe(1);
    }
  });

  it('a Faerie on top: asked, revealed, and the opponent loses 2', () => {
    const s = upkeep('Test Sprite');
    expect(s.pendingDecision?.options).toEqual(['Reveal it', 'Keep it hidden']);
    const theirs = life(s, 1);
    const yes = finish(drain(apply(s, { type: 'auto:decide', by: 0, cards: [], option: 'Reveal it' } as Action), 30));
    expect(life(yes, 1)).toBe(theirs - 2);
    const no = finish(drain(apply(s, { type: 'auto:decide', by: 0, cards: [], option: 'Keep it hidden' } as Action), 30));
    expect(life(no, 1)).toBe(theirs);
  });

  it('a changeling shares every type; a Bear shares none and nothing is asked', () => {
    const kin = upkeep('Test Shifter');
    expect(kin.pendingDecision?.options).toEqual(['Reveal it', 'Keep it hidden']);
    const bear = finish(upkeep('Test Bear'));
    expect(bear.pendingDecision).toBeNull();
    expect(life(bear, 1)).toBe(20);
  });
});

describe('the total power of creatures you control (D1076)', () => {
  const R = (name: string, type: string, cost: string, cmc: number, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: cost, cmc, colors: ['G'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Ghalta', 'Creature — Dinosaur', '{4}{G}{G}', 6, 'This spell costs {X} less to cast, where X is the total power of creatures you control.', ['6', '6']),
    R('Test Feast', 'Sorcery', '{0}', 0, 'You gain life equal to the total power of creatures you control with flying.'),
    R('Test Bird', 'Creature — Bird', '{0}', 0, 'Flying', ['1', '2']),
    R('Test Bear', 'Creature — Bear', '{0}', 0, '', ['3', '1']),
    R('Test Chief', 'Creature — Human', '{0}', 0, '{0}: You gain life equal to the total power of other creatures you control.', ['5', '5']),
  ];
  const deck = customDeck({ id: 'd1076', name: 'Total', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 52 }], data: ROWS as never[] });
  const table = (mine: string[], hand: string) => advanceTo(arena({
    decks: { 0: 'd1076', 1: 'd1076' }, deckSpecs: { d1076: deck.deck },
    battlefield: { 0: ['Forest', 'Forest', ...mine], 1: [] }, hands: { 0: [hand] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const castOf = (s: GameState, card: string) => ({ type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card) } as Action);

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of [...ROWS.slice(0, 2), ROWS[4]!]) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
  });

  it('four power on board makes a six-drop cost two; three does not', () => {
    const four = table(['Test Bear', 'Test Bird'], 'Test Ghalta');
    expect(refusal(four, castOf(four, 'Test Ghalta'))).toBeNull();
    const three = table(['Test Bear'], 'Test Ghalta');
    expect(refusal(three, castOf(three, 'Test Ghalta'))).not.toBeNull();
  });

  it('"with flying": only the fliers count', () => {
    let s = table(['Test Bear', 'Test Bird', 'Test Bird'], 'Test Feast');
    const before = life(s, 0);
    s = drain(passBoth(apply(s, castOf(s, 'Test Feast'))), 30);
    expect(life(s, 0)).toBe(before + 2);
  });

  it('"other creatures": not the one whose ability it is', () => {
    let s = table(['Test Bear', 'Test Chief'], 'Test Feast');
    const before = life(s, 0);
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: find(s, 0, 'battlefield', 'Test Chief'), abilityIndex: 0 } as Action)), 30);
    expect(life(s, 0)).toBe(before + 3);
  });
});

describe('"if you control a creature with flying / with a counter on it" (D1077)', () => {
  const R = (name: string, type: string, cost: string, cmc: number, text: string, pt?: [string, string]) => ({
    name, type_line: type, mana_cost: cost, cmc, colors: ['U'], layout: 'normal', oracle_text: text,
    ...(pt === undefined ? {} : { power: pt[0], toughness: pt[1] }),
  });
  const ROWS = [
    R('Test Gust', 'Instant', '{2}{U}', 3, 'This spell costs {2} less to cast if you control a creature with flying.\nDraw a card.'),
    R('Test Turtle', 'Creature — Turtle', '{2}{U}', 3, 'This spell costs {2} less to cast if you control a creature with a +1/+1 counter on it.', ['3', '3']),
    R('Test Bird', 'Creature — Bird', '{0}', 0, 'Flying', ['1', '1']),
    R('Test Bear', 'Creature — Bear', '{0}', 0, '', ['2', '2']),
  ];
  const deck = customDeck({ id: 'd1077', name: 'With', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Island', count: 52 }], data: ROWS as never[] });
  const table = (mine: string[], hand: string) => advanceTo(arena({
    decks: { 0: 'd1077', 1: 'd1077' }, deckSpecs: { d1077: deck.deck },
    battlefield: { 0: ['Island', ...mine], 1: [] }, hands: { 0: [hand] }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const castOf = (s: GameState, card: string) => ({ type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card) } as Action);

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    // A word that is not a keyword is not a quality the reader may guess at.
    const odd = compileCard(R('Test Odd', 'Instant', '{2}{U}', 3, 'This spell costs {2} less to cast if you control a creature with wings.\nDraw a card.') as never);
    expect(odd.ok && odd.unread.length).toBe(1);
  });

  it('a flier makes it cost one; a Bear does not', () => {
    const flier = table(['Test Bird'], 'Test Gust');
    expect(refusal(flier, castOf(flier, 'Test Gust'))).toBeNull();
    const ground = table(['Test Bear'], 'Test Gust');
    expect(refusal(ground, castOf(ground, 'Test Gust'))).not.toBeNull();
  });

  it('a creature with a +1/+1 counter on it, and not one without', () => {
    const plain = table(['Test Bear'], 'Test Turtle');
    expect(refusal(plain, castOf(plain, 'Test Turtle'))).not.toBeNull();
    const bear = find(plain, 0, 'battlefield', 'Test Bear');
    const countered = { ...plain, instances: { ...plain.instances, [bear]: { ...plain.instances[bear]!, counters: { '+1/+1': 1 } } } } as GameState;
    expect(refusal(countered, castOf(countered, 'Test Turtle'))).toBeNull();
  });
});

describe('entering with counters of its own (D1078)', () => {
  const C = (name: string, text: string, pt: [string, string]) => ({
    name, type_line: 'Creature — Phyrexian', mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', oracle_text: text, power: pt[0], toughness: pt[1],
  });
  const ROWS = [
    C('Test Raptor', 'Test Raptor enters with three oil counters on it.\nRemove an oil counter from Test Raptor: Test Raptor gets +1/+1 until end of turn.', ['2', '2']),
    C('Test Shrunk', 'Test Shrunk enters with two -1/-1 counters on it.', ['4', '4']),
  ];
  const deck = customDeck({ id: 'd1078', name: 'Own counters', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 56 }], data: ROWS as never[] });
  const enter = (card: string) => {
    const s = advanceTo(arena({
      decks: { 0: 'd1078', 1: 'd1078' }, deckSpecs: { d1078: deck.deck },
      battlefield: { 0: ['Swamp'], 1: [] }, hands: { 0: [card] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const t = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', card) } as Action)), 30);
    return { s: t, id: find(t, 0, 'battlefield', card) };
  };

  it('reads every row whole; a rules counter or a size counter it cannot apply stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    for (const counter of ['three time counters', 'a finality counter', 'a +1/+0 counter', 'a lore counter']) {
      const odd = compileCard(C('Test Odd', `Test Odd enters with ${counter} on it.`, ['1', '1']) as never);
      expect(odd.ok && odd.unread.length, counter).toBe(1);
    }
  });

  it('three oil counters on arrival, spent by its own ability', () => {
    let { s, id } = enter('Test Raptor');
    expect(s.instances[id]!.counters['oil']).toBe(3);
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: id, abilityIndex: 0 } as Action)), 30);
    expect(s.instances[id]!.counters['oil']).toBe(2);
    expect(power(s, id)).toBe(3);
  });

  it('two -1/-1 counters make a 4/4 a 2/2', () => {
    const { s, id } = enter('Test Shrunk');
    expect(s.instances[id]!.counters['-1/-1']).toBe(2);
    expect([power(s, id), characteristicsOf(s, s.instances[id]!).toughness]).toEqual([2, 2]);
  });
});

describe('an oil or charge counter on a target (D1079)', () => {
  const A = (name: string, text: string) => ({ name, type_line: 'Artifact', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', oracle_text: text });
  const ROWS = [A('Test Oiler', '{T}: Put an oil counter on target artifact you control.'), A('Test Relic', '')];
  const deck = customDeck({ id: 'd1079', name: 'Oil', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 56 }], data: ROWS as never[] });

  it('reads whole, aimed as a gift, and the counter goes on the target', () => {
    expect(deck.unknown).toEqual([]);
    const read = compileCard(ROWS[0] as never);
    expect(read).toMatchObject({ ok: true, unread: [] });
    expect(read.ok && read.script?.abilities?.[0]?.targets?.[0]?.friendly).toBe(true);
    let s = advanceTo(arena({
      decks: { 0: 'd1079', 1: 'd1079' }, deckSpecs: { d1079: deck.deck },
      battlefield: { 0: ['Test Oiler', 'Test Relic'], 1: [] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const relic = find(s, 0, 'battlefield', 'Test Relic');
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: find(s, 0, 'battlefield', 'Test Oiler'), abilityIndex: 0, targets: [{ kind: 'card', id: relic }] } as Action)), 30);
    expect(s.instances[relic]!.counters['oil']).toBe(1);
  });
});

describe('"its power" after the clause that aimed at it (D1080)', () => {
  const I = (name: string, text: string) => ({ name, type_line: 'Instant', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', oracle_text: text });
  const ROWS = [
    I('Test Chastise', 'Destroy target creature. You gain life equal to its power.'),
    I('Test Scars', "Regenerate target creature. You gain life equal to that creature's toughness."),
    I('Test Growth', 'Target creature gets +3/+3 until end of turn.'),
    I('Test Bless', 'Target creature gets +2/+2 until end of turn. You gain life equal to its toughness.'),
    { name: 'Test Bear', type_line: 'Creature — Bear', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: '', power: '2', toughness: '4' },
  ];
  const deck = customDeck({ id: 'd1080', name: 'Its power', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Plains', count: 52 }], data: ROWS as never[] });
  const table = (hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1080', 1: 'd1080' }, deckSpecs: { d1080: deck.deck },
    battlefield: { 0: ['Plains'], 1: ['Test Bear'] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const cast = (s: GameState, spell: string, id: string) =>
    drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', spell), targets: [{ kind: 'card', id }] } as Action)), 30);

  it('reads every row whole; "its power" with nothing aimed at before it stays unread', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS.slice(0, 2)) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
    const odd = compileCard(I('Test Odd', 'You gain life equal to its power.') as never);
    expect(odd.ok && odd.unread.length).toBe(1);
  });

  it('destroyed: the power it last had, pump included (CR 608.2h)', () => {
    let s = table(['Test Growth', 'Test Chastise']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    s = cast(s, 'Test Growth', bear);
    const before = life(s, 0);
    s = cast(s, 'Test Chastise', bear);
    expect(s.instances[bear]!.zone).toBe('graveyard');
    expect(life(s, 0)).toBe(before + 5);
  });

  it('changed by the clause before and still there: the value now, not the snapshot', () => {
    let s = table(['Test Bless']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    const before = life(s, 0);
    s = cast(s, 'Test Bless', bear);
    expect(life(s, 0)).toBe(before + 6);
  });

  it('still there: its toughness now', () => {
    let s = table(['Test Scars']);
    const bear = find(s, 1, 'battlefield', 'Test Bear');
    const before = life(s, 0);
    s = cast(s, 'Test Scars', bear);
    expect(life(s, 0)).toBe(before + 4);
  });
});

describe('"that creature\'s toughness" after an edict (D1081)', () => {
  const ROWS = [
    { name: 'Test Tribute', type_line: 'Instant', mana_cost: '{0}', cmc: 0, colors: ['B'], layout: 'normal', oracle_text: "Target opponent sacrifices a creature. You gain life equal to that creature's toughness." },
    { name: 'Test Growth', type_line: 'Instant', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: 'Target creature gets +3/+3 until end of turn.' },
    { name: 'Test Wall', type_line: 'Creature — Wall', mana_cost: '{0}', cmc: 0, colors: ['W'], layout: 'normal', oracle_text: '', power: '0', toughness: '5' },
  ];
  const deck = customDeck({ id: 'd1081', name: 'Tribute', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Swamp', count: 54 }], data: ROWS as never[] });

  it('reads whole; "that creature\'s toughness" with no question before it stays unread', () => {
    expect(deck.unknown).toEqual([]);
    expect(compileCard(ROWS[0] as never)).toMatchObject({ ok: true, unread: [] });
    const odd = compileCard({ ...ROWS[0], name: 'Test Odd', oracle_text: "You gain life equal to that creature's toughness." } as never);
    expect(odd.ok && odd.unread.length).toBe(1);
  });

  it('the sacrificed creature\'s toughness as it last was, pump included', () => {
    let s = advanceTo(arena({
      decks: { 0: 'd1081', 1: 'd1081' }, deckSpecs: { d1081: deck.deck },
      battlefield: { 0: ['Swamp'], 1: ['Test Wall'] }, hands: { 0: ['Test Growth', 'Test Tribute'] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const wall = find(s, 1, 'battlefield', 'Test Wall');
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Growth'), targets: [{ kind: 'card', id: wall }] } as Action)), 30);
    const before = life(s, 0);
    s = passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Tribute'), targets: [{ kind: 'player', seat: 1 }] } as Action));
    if (s.pendingDecision !== null) s = apply(s, { type: 'auto:decide', by: 1, cards: [wall] } as Action);
    s = drain(s, 30);
    expect(s.instances[wall]!.zone).toBe('graveyard');
    expect(life(s, 0)).toBe(before + 8);
  });
});

describe('an additional land this turn, and a permanent that tucks itself (D1082)', () => {
  const ROWS = [
    { name: 'Test Spiral', type_line: 'Instant', mana_cost: '{0}', cmc: 0, colors: ['G'], layout: 'normal', oracle_text: 'Draw a card. You may play an additional land this turn.' },
    { name: 'Test Top', type_line: 'Artifact', mana_cost: '{0}', cmc: 0, colors: [], layout: 'normal', oracle_text: "{T}: Draw a card, then put Test Top on top of its owner's library." },
  ];
  const deck = customDeck({ id: 'd1082', name: 'Spiral', entries: [...ROWS.map((r) => ({ name: r.name, count: 2 })), { name: 'Forest', count: 56 }], data: ROWS as never[] });
  const table = (battlefield: string[], hand: string[]) => advanceTo(arena({
    decks: { 0: 'd1082', 1: 'd1082' }, deckSpecs: { d1082: deck.deck },
    battlefield: { 0: battlefield, 1: [] }, hands: { 0: hand }, turn: 3, firstSeat: 0,
  }), 'precombat-main');

  it('reads every row whole', () => {
    expect(deck.unknown).toEqual([]);
    for (const r of ROWS) expect(compileCard(r as never), r.name).toMatchObject({ ok: true, unread: [] });
  });

  it('a second land may be played this turn, and not a third', () => {
    let s = table([], ['Test Spiral', 'Forest', 'Forest', 'Forest']);
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Spiral') } as Action)), 30);
    s = apply(s, { type: 'auto:playLand', by: 0, card: find(s, 0, 'hand', 'Forest') } as Action);
    expect(refusal(s, { type: 'auto:playLand', by: 0, card: find(s, 0, 'hand', 'Forest') } as Action)).toBeNull();
    s = apply(s, { type: 'auto:playLand', by: 0, card: find(s, 0, 'hand', 'Forest') } as Action);
    expect(refusal(s, { type: 'auto:playLand', by: 0, card: find(s, 0, 'hand', 'Forest') } as Action)).not.toBeNull();
  });

  it('draws, then goes on top of its owner\'s library', () => {
    let s = table(['Test Top'], []);
    const top = find(s, 0, 'battlefield', 'Test Top');
    const hand = ids(s, 0, 'hand').length;
    s = drain(passBoth(apply(s, { type: 'auto:activate', by: 0, card: top, abilityIndex: 0 } as Action)), 30);
    expect(ids(s, 0, 'hand').length).toBe(hand + 1);
    expect(ids(s, 0, 'library')[0]).toBe(top);
  });

  it('gone in response: it stays where it went', () => {
    let s = table(['Test Top'], []);
    const top = find(s, 0, 'battlefield', 'Test Top');
    s = apply(s, { type: 'auto:activate', by: 0, card: top, abilityIndex: 0 } as Action);
    s = apply(s, { type: 'card:move', by: 0, card: top, toZone: 'hand' } as Action);
    s = drain(passBoth(s), 30);
    expect(s.instances[top]!.zone).toBe('hand');
  });
});

describe('lands you control have a mana ability (D779)', () => {
  const LANTERN = { name: 'Test Lantern', type_line: 'Artifact', mana_cost: '{3}', cmc: 3, colors: [], layout: 'normal', oracle_text: 'Lands you control have "{T}: Add one mana of any color."' };
  const BLUE = { name: 'Test Blue Draw', type_line: 'Sorcery', mana_cost: '{U}', cmc: 1, colors: ['U'], layout: 'normal', oracle_text: 'Draw a card.' };
  const deck = customDeck({
    id: 'd779', name: 'Lantern',
    entries: [{ name: 'Test Lantern', count: 2 }, { name: 'Test Blue Draw', count: 4 }, { name: 'Forest', count: 54 }],
    data: [LANTERN, BLUE] as never[],
  });
  const table = (mine: string[]) => advanceTo(arena({
    decks: { 0: 'd779', 1: 'd779' }, deckSpecs: { d779: deck.deck },
    hands: { 0: ['Test Blue Draw'] }, battlefield: { 0: mine }, turn: 3, firstSeat: 0,
  }), 'precombat-main');
  const offered = (s: GameState) => legalActions(s, 0).plays.some((p) => p.kind === 'cast' && p.card === find(s, 0, 'hand', 'Test Blue Draw'));

  it('reads', () => {
    expect(compileCard(LANTERN as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('a Forest makes blue with the Lantern out, and the spell resolves', () => {
    let s = table(['Forest', 'Test Lantern']);
    expect(offered(s)).toBe(true);
    const before = ids(s, 0, 'hand').length;
    s = drain(passBoth(apply(s, { type: 'auto:cast', by: 0, card: find(s, 0, 'hand', 'Test Blue Draw') })));
    expect(ids(s, 0, 'hand').length).toBe(before);
    expect(s.instances[find(s, 0, 'battlefield', 'Forest')]!.tapped).toBe(true);
  });

  it('without the Lantern, a Forest cannot', () => {
    expect(offered(table(['Forest']))).toBe(false);
  });

  it('Frantic Search: draw two, discard two, and untap up to three lands', () => {
    const SEARCH = { name: 'Test Search', type_line: 'Instant', mana_cost: '{2}{U}', cmc: 3, colors: ['U'], layout: 'normal', oracle_text: 'Draw two cards, then discard two cards. Untap up to three lands.' };
    expect(compileCard(SEARCH as never)).toMatchObject({ ok: true, unread: [] });
    const d = customDeck({
      id: 'd779b', name: 'Search',
      entries: [{ name: 'Test Search', count: 4 }, { name: 'Island', count: 56 }],
      data: [SEARCH] as never[],
    });
    let s = advanceTo(arena({
      decks: { 0: 'd779b', 1: 'd779b' }, deckSpecs: { d779b: d.deck },
      hands: { 0: ['Test Search', 'Test Search'] }, battlefield: { 0: ['Island', 'Island', 'Island'] }, turn: 3, firstSeat: 0,
    }), 'precombat-main');
    const spell = find(s, 0, 'hand', 'Test Search');
    const held = ids(s, 0, 'hand').length - 1;
    s = passBoth(apply(s, { type: 'auto:cast', by: 0, card: spell }));
    // Drawn first: the two new cards are in hand when the discard is asked.
    expect(s.pendingDecision?.seat).toBe(0);
    expect(ids(s, 0, 'hand')).toHaveLength(held + 2);
    const hand = ids(s, 0, 'hand');
    s = apply(s, { type: 'auto:decide', by: 0, cards: hand.slice(0, 2) });
    const lands = ids(s, 0, 'battlefield');
    expect(lands.every((id) => s.instances[id]!.tapped)).toBe(true);
    s = drain(apply(s, { type: 'auto:decide', by: 0, cards: lands }));
    expect(ids(s, 0, 'hand')).toHaveLength(held);
    // The two discarded and the spell itself.
    expect(namesIn(s, 0, 'graveyard')).toHaveLength(3);
    expect(lands.every((id) => !s.instances[id]!.tapped)).toBe(true);
  });
});
describe('an attack tax: Propaganda and Ghostly Prison (D780)', () => {
  const PROP = { name: 'Test Propaganda', type_line: 'Enchantment', mana_cost: '{2}{U}', cmc: 3, colors: ['U'], layout: 'normal', oracle_text: "Creatures can't attack you unless their controller pays {2} for each creature they control that's attacking you." };
  const OX = { name: 'Test Ox', type_line: 'Creature — Ox', mana_cost: '{1}{G}', cmc: 2, colors: ['G'], layout: 'normal', power: '2', toughness: '2', oracle_text: '' };
  const deck = customDeck({
    id: 'd780', name: 'Propaganda',
    entries: [{ name: 'Test Propaganda', count: 2 }, { name: 'Test Ox', count: 4 }, { name: 'Forest', count: 54 }],
    data: [PROP, OX] as never[],
  });
  const table = (mine: string[], theirs: string[] = ['Test Propaganda']) => advanceTo(arena({
    decks: { 0: 'd780', 1: 'd780' }, deckSpecs: { d780: deck.deck },
    battlefield: { 0: mine, 1: theirs }, turn: 3, firstSeat: 0,
  }), 'declare-attackers');
  const oxen = (s: GameState) => ids(s, 0, 'battlefield').filter((id) => s.cardDefs[s.instances[id]!.defKey]?.name === 'Test Ox');
  const forests = (s: GameState) => ids(s, 0, 'battlefield').filter((id) => s.cardDefs[s.instances[id]!.defKey]?.name === 'Forest');

  it('reads', () => {
    expect(compileCard(PROP as never)).toMatchObject({ ok: true, unread: [] });
  });

  it('one attacker: {2} is paid from the lands, and it attacks', () => {
    let s = table(['Forest', 'Forest', 'Test Ox', 'Test Ox']);
    s = apply(s, { type: 'auto:attack', by: 0, attackers: [{ attacker: oxen(s)[0]!, defender: 1 }] });
    expect(s.combat.attacks).toHaveLength(1);
    expect(forests(s).every((id) => s.instances[id]!.tapped)).toBe(true);
  });

  it('two attackers need {4}: with two lands it is refused, and nothing is spent', () => {
    const s = table(['Forest', 'Forest', 'Test Ox', 'Test Ox']);
    const both = oxen(s).map((attacker) => ({ attacker, defender: 1 as SeatIndex }));
    expect(refusal(s, { type: 'auto:attack', by: 0, attackers: both })).toContain('{4}');
  });

  it('no tax without the enchantment, and none for attacking with nothing', () => {
    let s = table(['Test Ox', 'Test Ox'], []);
    s = apply(s, { type: 'auto:attack', by: 0, attackers: oxen(s).map((attacker) => ({ attacker, defender: 1 as SeatIndex })) });
    expect(s.combat.attacks).toHaveLength(2);
    const t = apply(table(['Test Ox']), { type: 'auto:attack', by: 0, attackers: [] });
    expect(t.combat.attackersDeclared).toBe(true);
  });

  it('the bot attacks with what it can pay for', () => {
    // At 4 life, three 2/2s look lethal; only one can be paid for.
    let s = table(['Forest', 'Forest', 'Test Ox', 'Test Ox', 'Test Ox']);
    s = { ...s, seats: s.seats.map((seat) => (seat.index === 1 ? { ...seat, life: 4 } : seat)) };
    const action = botAction(s, 0);
    expect(action?.type).toBe('auto:attack');
    const attackers = (action as { attackers: readonly unknown[] }).attackers;
    // One, not none: the plan is trimmed to what it can pay, not thrown away.
    expect(attackers).toHaveLength(1);
    expect(() => apply(s, action!)).not.toThrow();
  });
});
